-- Vitlion CMS — schema and current content.
-- Generated from the site source; paste into the Neon SQL Editor.
-- Safe to re-run: tables are created only if absent and rows are upserted.

CREATE TABLE IF NOT EXISTS translations (
  key varchar(191) NOT NULL,
  lang varchar(2) NOT NULL,
  value jsonb NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (key, lang)
);

CREATE TABLE IF NOT EXISTS page_seo (
  slug varchar(191) NOT NULL,
  lang varchar(2) NOT NULL,
  title varchar(255),
  description text,
  h1 varchar(255),
  cta_label varchar(191),
  indexable boolean NOT NULL DEFAULT false,
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (slug, lang)
);

CREATE TABLE IF NOT EXISTS content_blocks (
  id serial PRIMARY KEY,
  owner_type varchar(16) NOT NULL,
  owner_slug varchar(191) NOT NULL,
  lang varchar(2) NOT NULL,
  position integer NOT NULL DEFAULT 0,
  heading varchar(255),
  paragraphs jsonb,
  items jsonb,
  outro jsonb,
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS owner_idx ON content_blocks (owner_type, owner_slug, lang);

CREATE TABLE IF NOT EXISTS categories (
  slug varchar(191) PRIMARY KEY,
  main_image varchar(512),
  position integer NOT NULL DEFAULT 0,
  published boolean NOT NULL DEFAULT true,
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS models (
  slug varchar(191) PRIMARY KEY,
  category_slug varchar(191) NOT NULL,
  main_image varchar(512),
  gallery jsonb,
  position integer NOT NULL DEFAULT 0,
  published boolean NOT NULL DEFAULT true,
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS category_idx ON models (category_slug);

CREATE TABLE IF NOT EXISTS catalog_text (
  entity_type varchar(16) NOT NULL,
  slug varchar(191) NOT NULL,
  lang varchar(2) NOT NULL,
  name varchar(255),
  short text,
  description text,
  features jsonb,
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (entity_type, slug, lang)
);

CREATE TABLE IF NOT EXISTS faq_items (
  id serial PRIMARY KEY,
  lang varchar(2) NOT NULL,
  position integer NOT NULL DEFAULT 0,
  question text NOT NULL,
  answer text NOT NULL,
  published boolean NOT NULL DEFAULT true,
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS lang_idx ON faq_items (lang);

CREATE TABLE IF NOT EXISTS media (
  id serial PRIMARY KEY,
  path varchar(512) NOT NULL UNIQUE,
  public_id varchar(255),
  original_name varchar(255),
  width integer,
  height integer,
  bytes integer,
  alt varchar(255),
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS users (
  id serial PRIMARY KEY,
  email varchar(191) NOT NULL UNIQUE,
  password_hash varchar(255) NOT NULL,
  name varchar(191),
  created_at timestamptz NOT NULL DEFAULT now()
);

