INSERT INTO translations (key, lang, value) VALUES ('hero.titleSuffix', 'he', '"פרגולות, זיגוג ומסכי ZIP"'::jsonb) ON CONFLICT (key, lang) DO UPDATE SET value = excluded.value, updated_at = now();
INSERT INTO translations (key, lang, value) VALUES ('hero.titleSuffix', 'ru', '"перголы, остекление и ZIP-шторы"'::jsonb) ON CONFLICT (key, lang) DO UPDATE SET value = excluded.value, updated_at = now();
INSERT INTO translations (key, lang, value) VALUES ('hero.subtitle', 'he', '"עיצוב, ייצור והתקנה מקצועית של מבנים מאלומיניום וזכוכית במרכז, בצפון ובדרום הארץ - מתל אביב וחיפה ועד באר שבע. פרגולות קבועות וחשמליות, זכוכיות נאספות, גיליוטינות ומסכי ZIP - מיוצרים במפעל שלנו בישראל ומגיעים עם אחריות של 10 שנים."'::jsonb) ON CONFLICT (key, lang) DO UPDATE SET value = excluded.value, updated_at = now();
INSERT INTO translations (key, lang, value) VALUES ('hero.subtitle', 'ru', '"Проектирование, производство и профессиональный монтаж алюминиевых и стеклянных конструкций в центре, на севере и на юге страны — от Тель-Авива и Хайфы до Беэр-Шевы. Стационарные и электрические перголы, безрамное остекление, гильотины и ZIP-шторы — производятся на нашем заводе в Израиле, с гарантией 10 лет."'::jsonb) ON CONFLICT (key, lang) DO UPDATE SET value = excluded.value, updated_at = now();
