INSERT INTO translations (key, lang, value) VALUES ('meta.ogDescription', 'he', '"פרגולות, זיגוג, וילונות ZIP ומערכות הזזה. מחזור מלא: עיצוב, ייצור, התקנה."'::jsonb) ON CONFLICT (key, lang) DO UPDATE SET value = excluded.value, updated_at = now();
