INSERT INTO page_seo (slug, lang, title, description, h1, cta_label, indexable) VALUES ('services', 'he', 'פרגולות אלומיניום | חשמליות, קבועות וזכוכית | Vitlion', 'פרגולות אלומיניום יוקרתיות: פרגולות חשמליות ביוקלימטיות, פרגולות קבועות, תריסי ZIP, זכוכיות נאספות, גיליוטינות וגגות זכוכית. תכנון, ייצור והתקנה מקצועית בישראל. קבלו הצעת מחיר. Vitlion Group.', 'פרגולות אלומיניום - פתרונות הצללה וסגירה יוקרתיים', 'לקבלת הצעת מחיר', true) ON CONFLICT (slug, lang) DO UPDATE SET title = excluded.title, description = excluded.description, h1 = excluded.h1, cta_label = excluded.cta_label, indexable = excluded.indexable, updated_at = now();
INSERT INTO page_seo (slug, lang, title, description, h1, cta_label, indexable) VALUES ('services', 'ru', 'Алюминиевые перголы, остекление и ZIP | Vitlion', 'Алюминиевые перголы премиум-класса: биоклиматические электрические перголы, статичные перголы, ZIP-роллеты, безрамное остекление, гильотины и стеклянные крыши. Проектирование, производство и монтаж в Израиле. Получите расчёт. Vitlion Group.', 'Алюминиевые перголы - премиальные решения для навеса и остекления', 'Получить расчёт', true) ON CONFLICT (slug, lang) DO UPDATE SET title = excluded.title, description = excluded.description, h1 = excluded.h1, cta_label = excluded.cta_label, indexable = excluded.indexable, updated_at = now();
INSERT INTO page_seo (slug, lang, title, description, h1, cta_label, indexable) VALUES ('electric-pergolas', 'he', 'פרגולה חשמלית | ביוקלימטית עם שלבים מתכווננים | Vitlion', 'פרגולה חשמלית ביוקלימטית עם שלבים מתכווננים 0-90°. שליטה בשלט או באפליקציה, אטימות מלאה לגשם וחיבור לבית חכם. ייצור והתקנה מקצועית בישראל. הצעת מחיר. Vitlion.', 'פרגולות חשמליות - שליטה מלאה באור ובצל בלחיצת כפתור', 'לקבלת הצעת מחיר', true) ON CONFLICT (slug, lang) DO UPDATE SET title = excluded.title, description = excluded.description, h1 = excluded.h1, cta_label = excluded.cta_label, indexable = excluded.indexable, updated_at = now();
INSERT INTO page_seo (slug, lang, title, description, h1, cta_label, indexable) VALUES ('electric-pergolas', 'ru', 'Электрические перголы | Биоклиматик с ламелями | Vitlion', 'Электрическая биоклиматическая пергола с поворотными ламелями 0-90°. Управление пультом или приложением, полная защита от дождя и умный дом. Производство и монтаж в Израиле. Получите расчёт. Vitlion.', 'Электрические перголы - полный контроль света и тени в один клик', 'Получить расчёт', true) ON CONFLICT (slug, lang) DO UPDATE SET title = excluded.title, description = excluded.description, h1 = excluded.h1, cta_label = excluded.cta_label, indexable = excluded.indexable, updated_at = now();
INSERT INTO page_seo (slug, lang, title, description, h1, cta_label, indexable) VALUES ('static-pergolas', 'he', 'פרגולת אלומיניום קבועה | הייטק וקלאסית | Vitlion', 'פרגולה קבועה מאלומיניום בעיצוב הייטק או קלאסי. מבנה חזק ועמיד לשנים, קירוי סנטף BH, הגנה מלאה משמש וגשם. ייצור לפי מידה והתקנה בכל הארץ. הצעת מחיר. Vitlion.', 'פרגולת אלומיניום קבועה - עיצוב הייטק וקלאסי', 'לקבלת הצעת מחיר', true) ON CONFLICT (slug, lang) DO UPDATE SET title = excluded.title, description = excluded.description, h1 = excluded.h1, cta_label = excluded.cta_label, indexable = excluded.indexable, updated_at = now();
INSERT INTO page_seo (slug, lang, title, description, h1, cta_label, indexable) VALUES ('static-pergolas', 'ru', 'Стационарная алюминиевая пергола | Vitlion', 'Стационарная алюминиевая пергола в стиле хай-тек или классика. Прочная конструкция на годы, кровля Сантеф BH, полная защита от солнца и дождя. Производство по размеру и монтаж по Израилю. Получите расчёт. Vitlion.', 'Стационарная алюминиевая пергола - дизайн хай-тек и классика', 'Получить расчёт', true) ON CONFLICT (slug, lang) DO UPDATE SET title = excluded.title, description = excluded.description, h1 = excluded.h1, cta_label = excluded.cta_label, indexable = excluded.indexable, updated_at = now();
INSERT INTO page_seo (slug, lang, title, description, h1, cta_label, indexable) VALUES ('zip-shutters', 'he', 'מסך זיפ חשמלי | תריסי ZIP להגנה משמש ורוח | Vitlion', 'מסכי ZIP חשמליים ו-ZIP אופקי עם בד מתוח במסילות. הגנה משמש, רוח, אבק וחרקים, שליטה בשלט או אפליקציה. מתאים לפרגולות, מרפסות וטרסות. הצעת מחיר. Vitlion.', 'תריסי ZIP חשמליים - הגנה מלאה בלחיצת כפתור', 'לקבלת הצעת מחיר', true) ON CONFLICT (slug, lang) DO UPDATE SET title = excluded.title, description = excluded.description, h1 = excluded.h1, cta_label = excluded.cta_label, indexable = excluded.indexable, updated_at = now();
INSERT INTO page_seo (slug, lang, title, description, h1, cta_label, indexable) VALUES ('zip-shutters', 'ru', 'Электрические ZIP-роллеты | Vitlion', 'Электрические ZIP-роллеты (вертикальные и горизонтальные) с натянутым полотном в направляющих. Защита от солнца, ветра, пыли и насекомых. Для пергол, балконов и террас. Получите расчёт. Vitlion.', 'Электрические ZIP-роллеты - полная защита одним нажатием', 'Получить расчёт', true) ON CONFLICT (slug, lang) DO UPDATE SET title = excluded.title, description = excluded.description, h1 = excluded.h1, cta_label = excluded.cta_label, indexable = excluded.indexable, updated_at = now();
INSERT INTO page_seo (slug, lang, title, description, h1, cta_label, indexable) VALUES ('glazing', 'he', 'סגירת מרפסת זכוכית | זכוכיות נאספות וגיליוטינה | Vitlion', 'סגירת מרפסת בזכוכיות נאספות ללא מסגרת או בגיליוטינה חשמלית. מקסימום נוף, זכוכית מחוסמת ובטיחותית. ייצור והתקנה מקצועית בישראל. הצעת מחיר. Vitlion.', 'סגירת מרפסת בזכוכית - זכוכיות נאספות וגיליוטינה', 'לקבלת הצעת מחיר', true) ON CONFLICT (slug, lang) DO UPDATE SET title = excluded.title, description = excluded.description, h1 = excluded.h1, cta_label = excluded.cta_label, indexable = excluded.indexable, updated_at = now();
INSERT INTO page_seo (slug, lang, title, description, h1, cta_label, indexable) VALUES ('glazing', 'ru', 'Безрамное остекление и гильотина | Vitlion', 'Безрамное остекление балкона или электрическая гильотина. Максимум обзора, закалённое безопасное стекло. Производство и монтаж в Израиле. Получите расчёт. Vitlion.', 'Остекление балкона - безрамное остекление и гильотина', 'Получить расчёт', true) ON CONFLICT (slug, lang) DO UPDATE SET title = excluded.title, description = excluded.description, h1 = excluded.h1, cta_label = excluded.cta_label, indexable = excluded.indexable, updated_at = now();
INSERT INTO page_seo (slug, lang, title, description, h1, cta_label, indexable) VALUES ('glass-roofs', 'he', 'גג זכוכית קבוע וסקיילייט חשמלי | Vitlion', 'גג זכוכית קבוע וסקיילייט חשמלי - אור טבעי מקסימלי וחיבור מושלם בין פנים לחוץ. שליטה חשמלית באוורור וצל, זכוכית איכותית ועיצוב אדריכלי יוקרתי. הצעת מחיר. Vitlion.', 'גגות זכוכית - אור טבעי וחיבור מושלם בין פנים לחוץ', 'לקבלת הצעת מחיר', true) ON CONFLICT (slug, lang) DO UPDATE SET title = excluded.title, description = excluded.description, h1 = excluded.h1, cta_label = excluded.cta_label, indexable = excluded.indexable, updated_at = now();
INSERT INTO page_seo (slug, lang, title, description, h1, cta_label, indexable) VALUES ('glass-roofs', 'ru', 'Стационарная стеклянная крыша и скайлайт | Vitlion', 'Стационарная стеклянная крыша и электрический скайлайт - максимум естественного света и идеальная связь между домом и улицей. Электрическое управление вентиляцией и тенью, качественное стекло. Получите расчёт. Vitlion.', 'Стеклянные крыши - естественный свет и связь дома с улицей', 'Получить расчёт', true) ON CONFLICT (slug, lang) DO UPDATE SET title = excluded.title, description = excluded.description, h1 = excluded.h1, cta_label = excluded.cta_label, indexable = excluded.indexable, updated_at = now();
