INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'shlavey-zhuhit', 'he', 'ביוקלימטיק שלבי זכוכית', 'פרגולה חשמלית עם לוחות זכוכית לאור טבעי מקסימלי', 'ביוקלימטיק שלבי זכוכית הוא הפתרון המושלם למי שרוצה ליהנות מאור טבעי מקסימלי בו זמנית עם שליטה על אוורור. לוחות הזכוכית המחוסמת מאפשרים מעבר אור מלא כשהם סגורים ואוורור מעולה כשהם פתוחים. אידיאלי לגגות וטרסות בהן חשוב שמירת מראה בנוי.', '["לוחות זכוכית מחוסמת","אור טבעי מקסימלי","שליטה על אוורור","חשמלי עם שלט מרחוק","עיצוב פתוח ואלגנטי","אחריות 10 שנים"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'shlavey-zhuhit', 'ru', 'Биоклиматик со стеклянными ламелями', 'Электрическая пергола со стеклянными ламелями для максимального естественного света', 'Биоклиматик со стеклянными ламелями — идеальное решение для тех, кто хочет максимального естественного света при одновременном контроле вентиляции. Закалённые стеклянные ламели обеспечивают полное прохождение света в закрытом положении и отличную вентиляцию в открытом. Идеально для крыш и террас, где важно сохранение архитектурного вида.', '["Ламели из закалённого стекла","Максимальный естественный свет","Контроль вентиляции","Электрический с пультом ДУ","Открытый элегантный дизайн","Гарантия 10 лет"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
