INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'bioclimatic', 'he', 'ביוקלימטיק', 'פרגולה חשמלית עם לוחות מסתובבים לשליטה על אור, אוויר וצל', 'פרגולה ביוקלימטית היא פתרון מהפכני לאלה שמעריכים נוחות וטכנולוגיה מודרנית. לוחות אלומיניום מסתובבים ממונעים נשלטים מרחוק או דרך אפליקציה בסמארטפון. חיישני גשם ורוח מובנים סוגרים אוטומטית את הגג בזמן מזג אוויר רע. זמין עם אינטגרציה לבית חכם. המבנים מיוצרים לפי מידות אישיות ובכל צבע RAL.', '["שליטה דרך סמארטפון או שלט","חיישני גשם ורוח","אלומיניום אנודיזציה: לא מחליד","כל מידה לפי הזמנה","אינטגרציה לבית חכם","אחריות 10 שנים"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'bioclimatic', 'ru', 'Биоклиматик', 'Электрическая пергола с поворотными ламелями для управления светом, воздухом и тенью', 'Биоклиматическая пергола — революционное решение для тех, кто ценит комфорт и современные технологии. Поворотные алюминиевые ламели с электроприводом управляются дистанционно или через приложение в смартфоне. Встроенные датчики дождя и ветра автоматически закрывают крышу при плохой погоде. Доступна с интеграцией в систему умного дома. Конструкции изготавливаются по индивидуальным размерам и в любом цвете RAL.', '["Управление со смартфона или пульта","Датчики дождя и ветра","Анодированный алюминий: не ржавеет","Любой размер под заказ","Интеграция в умный дом","Гарантия 10 лет"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
