INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'bio-rolling', 'he', 'ביוקלימטיק Bio Rolling', 'פרגולה חשמלית עם לוחות נגללים לצל מיידי וגמישות מרבית', 'ביוקלימטיק Bio Rolling הוא גרסה ייחודית של הפרגולה החשמלית עם לוחות נגללים. בלחיצת כפתור, הלוחות נגללים ליצירת צל מלא או נפתחים לאוויר ולשמש. מתאים במיוחד לגגות עם מגבלות גובה. גמישות מרבית: שליטה על כמות האור בכל רגע נתון.', '["לוחות נגללים לצל מלא","שליטה מרחוק","מתאים לתקרות נמוכות","חיישני מזג אוויר","כל צבעי RAL","אחריות 10 שנים"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'bio-rolling', 'ru', 'Биоклиматик Bio Rolling', 'Электрическая пергола со сворачивающимися ламелями для мгновенного затенения', 'Bio Rolling — уникальная версия электрической перголы со сворачивающимися ламелями. Нажатием кнопки ламели сворачиваются для полного затенения или раскрываются для воздуха и солнца. Особенно подходит для крыш с ограничением высоты. Максимальная гибкость: контроль количества света в любой момент.', '["Сворачивающиеся ламели для полного затенения","Дистанционное управление","Подходит для низких потолков","Датчики погоды","Все цвета RAL","Гарантия 10 лет"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
