INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'rafafa', 'he', 'ביוקלימטיק רפפה', 'פרגולות עם לוחות מסתובבים לאפקט וויזואלי ייחודי', 'ביוקלימטיק רפפה הוא פתרון עיצובי ייחודי המשלב פונקציונליות עם אסתטיקה. הלוחות המתנדנדים יוצרים תנועה עדינה ברוח ומעניקים לחלל מראה דינמי ומיוחד. בנוסף לאפקט הוויזואלי, המבנה מספק הגנה מהשמש ומזג אוויר.', '["אפקט תנועה ייחודי","הגנה מהשמש ומהגשם","עיצוב אדריכלי מיוחד","אלומיניום באיכות פרמיום","כל מידה לפי הזמנה","אחריות 10 שנים"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'rafafa', 'ru', 'Биоклиматик Rafafa', 'Пергола с качающимися ламелями для уникального визуального эффекта', 'Биоклиматик Rafafa — уникальное дизайнерское решение, сочетающее функциональность с эстетикой. Качающиеся ламели создают нежное движение на ветру и придают пространству динамичный и особенный вид. Помимо визуального эффекта, конструкция обеспечивает защиту от солнца и непогоды.', '["Уникальный эффект движения","Защита от солнца и дождя","Особый архитектурный дизайн","Премиальный алюминий","Любые размеры под заказ","Гарантия 10 лет"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
