INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'pvc-pergula', 'he', 'פרגולת PVC', 'פרגולה חשמלית עם בד PVC לצל מלא והגנה מהגשם', 'פרגולת PVC היא פתרון יעיל לצל ולהגנה מהגשם. בד ה-PVC העמיד נשלט חשמלית ומאפשר סגירה מהירה בעת גשם. החומר עמיד לקרינת UV ולא מצהיב עם הזמן. אידיאלי למסעדות, מרפסות ובתי קפה שרוצים פתרון מהיר ואמין.', '["בד PVC עמיד UV","פתיחה/סגירה חשמלית","עמיד לגשם ורוח","מתאים למסחרי ופרטי","ניקוי ותחזוקה קלים","אחריות 10 שנים"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'pvc-pergula', 'ru', 'PVC-пергола', 'Электрическая пергола с тканью PVC для полного затенения и защиты от дождя', 'PVC-пергола — эффективное решение для затенения и защиты от дождя. Прочная ткань PVC управляется электрически и обеспечивает быстрое закрытие при дожде. Материал устойчив к UV-излучению и не желтеет со временем. Идеально для ресторанов, балконов и кафе, которым нужно быстрое и надёжное решение.', '["UV-стойкая ткань PVC","Электрическое открытие/закрытие","Устойчивость к дождю и ветру","Подходит для коммерческого и частного","Лёгкая чистка и обслуживание","Гарантия 10 лет"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
