INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'pvc-kshatit', 'he', 'פרגולת PVC קשתית', 'פרגולת PVC בצורת קשת לעיצוב ייחודי ויוקרתי', 'פרגולת PVC קשתית היא גרסה אלגנטית של פרגולת ה-PVC עם צורה קשתית ייחודית. הצורה הקשתית מעניקה לחלל מראה יוקרתי ואדריכלי. כמו פרגולת ה-PVC הרגילה, גם גרסה זו עמידה לתנאי מזג האוויר הישראלי ומספקת הגנה מהשמש ומהגשם.', '["צורה קשתית ייחודית","בד PVC עמיד","מראה יוקרתי","שליטה חשמלית","כל מידה לפי הזמנה","אחריות 10 שנים"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'pvc-kshatit', 'ru', 'PVC-пергола арочная', 'Арочная PVC-пергола для уникального роскошного дизайна', 'Арочная PVC-пергола — элегантная версия PVC-перголы с уникальной арочной формой. Арочная форма придаёт пространству роскошный и архитектурный вид. Как и обычная PVC-пергола, эта версия устойчива к условиям израильского климата и обеспечивает защиту от солнца и дождя.', '["Уникальная арочная форма","Прочная ткань PVC","Роскошный внешний вид","Электрическое управление","Любые размеры под заказ","Гарантия 10 лет"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
