INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'hi-tec-yashir', 'he', 'פרגולת היי-טק פסים חלקים', 'פרגולה סטטית עם פסים ישרים לעיצוב נקי ומינימליסטי', 'פרגולת היי-טק פסים חלקים היא פרגולה סטטית עם פרופילי אלומיניום ישרים בעיצוב מינימליסטי נקי. הפסים הישרים והחלקים יוצרים מראה מודרני ואלגנטי המשתלב עם כל סגנון אדריכלי עכשווי. מתאימה לבתים פרטיים, גגות ומרחבים חיצוניים שמחפשים קו נקי ומושלם.', '["פרופילים ישרים מינימליסטיים","עיצוב נקי ואלגנטי","אלומיניום באיכות פרמיום","כל צבעי RAL","מתאים לפרטי ומסחרי","אחריות 10 שנים"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'hi-tec-yashir', 'ru', 'Пергола Хай-тек с гладкими рейками', 'Статичная пергола с прямыми гладкими рейками для чистого минималистичного дизайна', 'Пергола Хай-тек с гладкими рейками — статичная пергола с прямыми алюминиевыми профилями в чистом минималистичном дизайне. Прямые гладкие рейки создают современный элегантный вид, гармонично вписывающийся в любой актуальный архитектурный стиль. Подходит для частных домов, крыш и внешних пространств, стремящихся к идеально чистой линии.', '["Минималистичные прямые профили","Чистый элегантный дизайн","Премиальный алюминий","Все цвета RAL","Подходит для частного и коммерческого","Гарантия 10 лет"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
INSERT INTO models (slug, category_slug, main_image, gallery, position) VALUES ('pergola-clasit', 'static-pergolas', '/media/services2/pergola-clasit/01.webp', '["/media/services2/pergola-clasit/01.webp","/media/services2/pergola-clasit/02.webp","/media/services2/pergola-clasit/03.webp","/media/services2/pergola-clasit/04.webp","/media/services2/pergola-clasit/05.webp","/media/services2/pergola-clasit/06.webp"]'::jsonb, 1) ON CONFLICT (slug) DO UPDATE SET category_slug = excluded.category_slug, main_image = excluded.main_image, gallery = excluded.gallery, position = excluded.position, updated_at = now();
INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'pergola-clasit', 'he', 'פרגולה קלאסית', 'פרגולה סטטית עם עיצוב נקי וצל קבוע לכל השנה', 'פרגולה קלאסית היא קלאסיקה של עיצוב אדריכלי בביצוע מודרני. היא יוצרת צל קבוע, מגנה מקרינת UV ונותנת למרחב מראה אסתטי מושלם. מסגרת האלומיניום אינה דורשת צביעה, לא נרקבת ולא מתעוותת תחת האקלים הישראלי. זמינה בלוחות קבועים בזוויות שונות.', '["עמידות לאקלים הישראלי","לא דורשת תחזוקה","זוויות נטייה שונות ללוחות","כל צבעי RAL","התקנה מיום עבודה אחד","אחריות 10 שנים"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'pergola-clasit', 'ru', 'Классическая пергола', 'Статичная пергола с чистым дизайном и постоянной тенью на весь год', 'Классическая пергола — это классика архитектурного дизайна в современном исполнении. Она создаёт постоянную тень, защищает от UV-излучения и придаёт пространству эстетически совершенный вид. Алюминиевый каркас не требует покраски, не гниёт и не деформируется в условиях израильского климата. Доступна с фиксированными ламелями под разными углами.', '["Устойчивость к израильскому климату","Не требует обслуживания","Разные углы наклона ламелей","Все цвета RAL","Установка от одного рабочего дня","Гарантия 10 лет"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
