INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'panel-mevudad', 'he', 'פרגולה מפנל מבודד', 'פרגולה עם פנל מבודד לבידוד תרמי מושלם בכל עונות השנה', 'פרגולה מפנל מבודד היא פתרון מעולה למי שרוצה לא רק צל אלא גם בידוד תרמי אמיתי. הפנל המבודד מורכב משתי שכבות אלומיניום עם מילוי פוליאוריטן, המספק בידוד תרמי מצוין. הפנל אטום למים לחלוטין, מאפשר שימוש גם בגשם, ומשמש כגג קבוע לסוכות ומרפסות מקורות.', '["בידוד תרמי מצוין","פנל אטום למים","שימוש בכל עונות השנה","גג קבוע ועמיד","ניתן לשילוב עם תאורה","אחריות 10 שנים"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'panel-mevudad', 'ru', 'Пергола из изолированной панели', 'Пергола с изолирующей панелью для идеальной теплоизоляции круглый год', 'Пергола из изолированной панели — отличное решение для тех, кто хочет не только тень, но и настоящую теплоизоляцию. Изолирующая панель состоит из двух слоёв алюминия с полиуретановым наполнителем, обеспечивающим превосходную теплоизоляцию. Панель полностью водонепроницаема, позволяет использовать пространство даже в дождь и служит постоянной крышей для беседок и закрытых балконов.', '["Превосходная теплоизоляция","Полностью водонепроницаемая панель","Использование в любое время года","Постоянная и прочная крыша","Возможна интеграция освещения","Гарантия 10 лет"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
