INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'hi-tech-meutsavim', 'he', 'פרגולת היי-טק פסים מעוצבים', 'פרגולה סטטית עם פסים מעוצבים לעיצוב אדריכלי ייחודי', 'פרגולת היי-טק פסים מעוצבים היא פרגולה סטטית אדריכלית עם פרופילי אלומיניום מעוצבים בצורות ייחודיות. הפסים המעוצבים מוסיפים אלמנט עיצובי בולט ומעניקים למבנה מראה מרשים ומיוחד. מתאימה לחזיתות בתים, גגות ומרפסות שדורשים מראה אדריכלי מבודל.', '["פרופילים מעוצבים ייחודיים","אלומיניום באיכות פרמיום","עיצוב אדריכלי מרשים","מתאים למסחרי ופרטי","כל צבעי RAL","אחריות 10 שנים"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'hi-tech-meutsavim', 'ru', 'Пергола Хай-тек с рифлёными рейками', 'Статичная пергола с рифлёными рейками для уникального архитектурного дизайна', 'Пергола Хай-тек с рифлёными рейками — архитектурная статичная пергола с алюминиевыми профилями уникальных форм. Рифлёные рейки добавляют выразительный дизайнерский элемент и придают конструкции впечатляющий особенный вид. Подходит для фасадов домов, крыш и балконов, требующих выдающегося архитектурного облика.', '["Уникальные рифлёные профили","Премиальный алюминий","Впечатляющий архитектурный дизайн","Подходит для коммерческого и частного","Все цвета RAL","Гарантия 10 лет"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
