INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'masahey-zip', 'he', 'מסכי ZIP', 'ZIP אנכי לסגירת צדדים של מרפסות, טרסות ומסעדות', 'מסכי ZIP הם וילונות אנכיים חדשניים מ-PVC שקוף הנדבקים היטב לפרופיל האלומיניום משני הצדדים הודות למדריכים צדדיים. בניגוד לוילונות רגילים, מסכי ZIP לא מתנפנפים ברוח ומבטיחים סגירה אטומה. אידיאלי למסעדות, מרפסות ומרפסות גג. מיוצר לפי מידות אישיות, מתאים לסגירת בין עמודי פרגולה ובין חזיתות הבניין.', '["סגירה אטומה: ללא פערים","לא מתנפנף ברוח","PVC שקוף עמיד UV","שליטה מכנית או חשמלית","מתאים לאתרים מסחריים","ניקוי ותחזוקה קלים"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'masahey-zip', 'ru', 'ZIP-экраны (вертикальный)', 'Вертикальный ZIP для закрытия боков балконов, террас и ресторанов', 'ZIP-экраны — инновационные вертикальные шторы из прозрачного PVC, надёжно крепящиеся к алюминиевому профилю с обеих сторон благодаря боковым направляющим. В отличие от обычных штор, ZIP-экраны не хлопают на ветру и обеспечивают герметичное закрытие. Идеально для ресторанов, балконов и кровельных террас. Изготавливаются по индивидуальным размерам, подходят для закрытия между стойками перголы и фасадами здания.', '["Герметичное закрытие: без зазоров","Не хлопает на ветру","Прозрачный UV-стойкий PVC","Механическое или электрическое управление","Подходит для коммерческих объектов","Лёгкая чистка и обслуживание"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
INSERT INTO models (slug, category_slug, main_image, gallery, position) VALUES ('zip-ofaki', 'zip-shutters', '/media/services2/zip-ofaki/01.webp', '["/media/services2/zip-ofaki/01.webp","/media/services2/zip-ofaki/02.webp","/media/services2/zip-ofaki/03.webp","/media/services2/zip-ofaki/04.webp","/media/services2/zip-ofaki/05.webp"]'::jsonb, 1) ON CONFLICT (slug) DO UPDATE SET category_slug = excluded.category_slug, main_image = excluded.main_image, gallery = excluded.gallery, position = excluded.position, updated_at = now();
INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'zip-ofaki', 'he', 'ZIP אופקי', 'ZIP אופקי לכיסוי פתוח מלמעלה עם הגנה מהשמש ומהגשם', 'ZIP אופקי הוא פתרון חדשני לכיסוי מרחבים פתוחים ומרפסות. הווילון האופקי נפרש לרוחב הפתח ומספק הגנה מהשמש ומהגשם. הזיפ הצדדי מבטיח סגירה הרמטית שמונעת התנפנפות ברוח. מתאים כתוספת מעולה לפרגולות קיימות ולחללים חיצוניים ללא כיסוי.', '["סגירה הרמטית: ללא פערים","לא מתנפנף ברוח","PVC עמיד UV: לא מצהיב","שליטה מכנית או חשמלית","תוספת מעולה לפרגולה","ניקוי ותחזוקה קלים"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'zip-ofaki', 'ru', 'ZIP горизонтальный', 'Горизонтальный ZIP для покрытия открытого верха с защитой от солнца и дождя', 'Горизонтальный ZIP — инновационное решение для покрытия открытых пространств и балконов. Горизонтальный тент разворачивается по ширине проёма и обеспечивает защиту от солнца и дождя. Боковой ZIP обеспечивает герметичное закрытие, предотвращающее хлопание на ветру. Отлично подходит как дополнение к существующим перголам и незащищённым внешним пространствам.', '["Герметичное закрытие: без зазоров","Не хлопает на ветру","UV-стойкий PVC: не желтеет","Механическое или электрическое управление","Отличное дополнение к перголе","Лёгкая чистка и обслуживание"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
