INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'skylight', 'he', 'סקיילייט חשמלי', 'גג זכוכית חשמלי לאור טבעי מקסימלי עם שליטה פשוטה', 'סקיילייט חשמלי הוא גג זכוכית ממונע המאפשר שליטה קלה על כמות האור והאוורור. פתיחה חשמלית בלחיצת כפתור, עם חיישני גשם שסוגרים אוטומטית בעת גשם. הזכוכית המחוסמת מספקת בידוד תרמי ואקוסטי מצוין. פתרון פרמיום לגגות וטרסות.', '["פתיחה חשמלית בלחיצת כפתור","חיישני גשם אוטומטיים","זכוכית מחוסמת","בידוד תרמי ואקוסטי","שליטה מרחוק","אחריות 10 שנים"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'skylight', 'ru', 'Скайлайт электрический', 'Электрическая стеклянная крыша для максимального естественного света с простым управлением', 'Электрический скайлайт — мотоприводная стеклянная крыша с лёгким управлением количеством света и вентиляции. Электрическое открытие нажатием кнопки с датчиками дождя, автоматически закрывающимися при осадках. Закалённое стекло обеспечивает отличную тепло- и звукоизоляцию. Премиальное решение для крыш и террас.', '["Электрическое открытие нажатием кнопки","Автоматические датчики дождя","Закалённое стекло","Тепло- и звукоизоляция","Дистанционное управление","Гарантия 10 лет"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
INSERT INTO models (slug, category_slug, main_image, gallery, position) VALUES ('gag-zhuhit-kavua', 'glass-roofs', '/media/services2/gag-zhuhit-kavua/01.webp', '["/media/services2/gag-zhuhit-kavua/01.webp","/media/services2/gag-zhuhit-kavua/02.webp","/media/services2/gag-zhuhit-kavua/03.webp","/media/services2/gag-zhuhit-kavua/04.webp","/media/services2/gag-zhuhit-kavua/05.webp","/media/services2/gag-zhuhit-kavua/06.webp","/media/services2/glass-roofs/01.webp","/media/services2/glass-roofs/02.webp","/media/services2/glass-roofs/03.webp"]'::jsonb, 1) ON CONFLICT (slug) DO UPDATE SET category_slug = excluded.category_slug, main_image = excluded.main_image, gallery = excluded.gallery, position = excluded.position, updated_at = now();
INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'gag-zhuhit-kavua', 'he', 'גג זכוכית קבוע', 'גג זכוכית קבוע לאור טבעי כל השנה עם עמידות מקסימלית', 'גג זכוכית קבוע הוא פתרון אסתטי ועמיד לכיסוי מרחבים פתוחים. הזכוכית המחוסמת מספקת הגנה מלאה מהגשם תוך מעבר אור טבעי מקסימלי. מסגרת האלומיניום חזקה ועמידה לתנאי מזג האוויר הישראלי. אידיאלי לחצרות, מרפסות וגגות שרוצים לכסות ללא אובדן אור.', '["הגנה מלאה מהגשם","אור טבעי מקסימלי","זכוכית מחוסמת","מסגרת אלומיניום חזקה","כל מידה לפי הזמנה","אחריות 10 שנים"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'gag-zhuhit-kavua', 'ru', 'Постоянная стеклянная крыша', 'Постоянная стеклянная крыша для естественного света круглый год с максимальной прочностью', 'Постоянная стеклянная крыша — эстетичное и прочное решение для перекрытия открытых пространств. Закалённое стекло обеспечивает полную защиту от дождя при максимальном пропускании естественного света. Алюминиевый каркас прочен и устойчив к условиям израильского климата. Идеально для дворов, балконов и крыш, которые нужно перекрыть без потери света.', '["Полная защита от дождя","Максимальный естественный свет","Закалённое стекло","Прочный алюминиевый каркас","Любые размеры под заказ","Гарантия 10 лет"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
