INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'neesafot', 'he', 'זכוכיות נאספות', 'זיגוג מתקפל ללא מסגרת לפתיחה מלאה ואור מקסימלי', 'זכוכיות נאספות היא מערכת פאנלים זכוכית שמתקפלים כמו אקורדיון ופותחים את המרחב לחלוטין. ללא עמודי אלומיניום גלויים: רק זכוכית. אידיאלי לאיחוד חלל פנימי וחיצוני במרפסות, גגות ומרפסות קיץ. משתמשים בזכוכית מחוסמת לבטיחות מקסימלית.', '["פתיחה מלאה ללא עמודים","זכוכית מחוסמת","הזזה לכל כיוון","בידוד תרמי ואקוסטי","זמין עם מדריך עליון או תחתון","אפשרות להתקנת רשת"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'neesafot', 'ru', 'Складные стёкла', 'Бескаркасное складное остекление для полного открытия и максимального света', 'Складные стёкла — система стеклянных панелей, складывающихся как гармошка и полностью открывающих пространство. Без видимых алюминиевых стоек: только стекло. Идеально для объединения внутреннего и внешнего пространства на балконах, крышах и летних верандах. Используется закалённое стекло для максимальной безопасности.', '["Полное открытие без стоек","Закалённое стекло","Сдвиг в любом направлении","Тепло- и звукоизоляция","Верхний или нижний направляющий профиль","Возможность установки сетки"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
