INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'tzalon-kalua', 'he', 'נאספות עם צלון כלוא', 'זיגוג מתקפל עם צלון משולב לשליטה על אור ופרטיות', 'נאספות עם צלון כלוא הוא פתרון מתקדם המשלב זכוכיות נאספות עם צלון כלוא משולב בתוך הזכוכית. הצלון מאפשר שליטה מלאה על כמות האור והפרטיות ללא צורך בוילונות נפרדים. אידיאלי לחדרי שינה, חדרי ישיבות ומרפסות בהן חשובה הפרטיות.', '["צלון כלוא משולב בזכוכית","שליטה על אור ופרטיות","ללא ניקוי הצלון","מראה מינימליסטי","פתיחה מלאה ללא עמודים","אחריות 10 שנים"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'tzalon-kalua', 'ru', 'Складные стёкла с жалюзи', 'Складное остекление со встроенными жалюзи для управления светом и приватностью', 'Складные стёкла с жалюзи — продвинутое решение, объединяющее складные стёкла с интегрированными жалюзи внутри стекла. Жалюзи обеспечивают полный контроль над количеством света и приватностью без необходимости в отдельных шторах. Идеально для спален, переговорных комнат и балконов, где важна приватность.', '["Жалюзи встроены в стекло","Управление светом и приватностью","Не требует чистки жалюзи","Минималистичный вид","Полное открытие без стоек","Гарантия 10 лет"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
INSERT INTO models (slug, category_slug, main_image, gallery, position) VALUES ('gilyotina', 'glazing', '/media/services2/gilyotina/01.webp', '["/media/services2/gilyotina/01.webp","/media/services2/gilyotina/02.webp","/media/services2/gilyotina/03.webp"]'::jsonb, 2) ON CONFLICT (slug) DO UPDATE SET category_slug = excluded.category_slug, main_image = excluded.main_image, gallery = excluded.gallery, position = excluded.position, updated_at = now();
INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'gilyotina', 'he', 'גיליוטינה', 'זיגוג אנכי חשמלי עולה ויורד בלחיצת כפתור', 'גיליוטינה היא פאנל זכוכית הזזה אנכי עם כונן חשמלי. בלחיצת כפתור, קטע הזכוכית יורד או עולה בצורה חלקה. משמשות במסעדות, מרכזי קניות ובניינים מגורים ליצירת מרחבים פתוחים וסגורים. מראה מינימליסטי מודרני: ללא ידיות או אביזרים גלויים.', '["שליטה חשמלית חלקה","זכוכית בטיחות מחוסמת","אפשרות תכנות","עיצוב מינימליסטי","מתאים לפתחים גדולים","אינטגרציה לבית חכם"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
INSERT INTO catalog_text (entity_type, slug, lang, name, short, description, features) VALUES ('model', 'gilyotina', 'ru', 'Гильотина', 'Вертикальное электрическое остекление, поднимающееся и опускающееся нажатием кнопки', 'Гильотина — вертикальная сдвижная стеклянная панель с электроприводом. Нажатием кнопки стеклянная секция плавно опускается или поднимается. Используется в ресторанах, торговых центрах и жилых зданиях для создания открытых и закрытых пространств. Современный минималистичный вид: без ручек или видимых аксессуаров.', '["Плавное электрическое управление","Закалённое защитное стекло","Возможность программирования","Минималистичный дизайн","Подходит для больших проёмов","Интеграция в умный дом"]'::jsonb) ON CONFLICT (entity_type, slug, lang) DO UPDATE SET name = excluded.name, short = excluded.short, description = excluded.description, features = excluded.features, updated_at = now();
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('page', 'services', 'he', 0, 'פרגולות חשמליות', NULL, '["ביוקלימטיק — הלמלות נעות בו-זמנית בהזזה ובסבסוב, לשליטה מלאה באור ובאוורור.","ביוקלימטיק Bio Rolling — הלמלות רק נעות בהזזה לצד, והגג נפתח לחלוטין.","ביוקלימטיק רפאפה — הלמלות מסתובבות במקום בלבד, ללא הזזה, לכיוונון עדין של האור.","ביוקלימטיק עם למלות זכוכית — שילוב של שקיפות הזכוכית עם מכניקת הלמלות המסתובבות.","פרגולת PVC ישרה — גג גמיש ועמיד במים בצורה ישרה.","פרגולת PVC מקושתת — גג גמיש ועמיד במים בצורה מקושתת."]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('page', 'services', 'he', 1, 'פרגולות קבועות', NULL, '["פרגולת הייטק עם למלות ישרות — מראה נקי ומינימליסטי.","פרגולת הייטק עם למלות דקורטיביות בצדדים.","פרגולה קלאסית — פתרון משתלם מבלי להתפשר על האיכות.","פרגולה מפאנל תרמי — בידוד תרמי ואקוסטי מלא."]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('page', 'services', 'he', 2, 'תריסי ZIP', NULL, '["מסכי ZIP — התקנה אנכית בצדדים, הגנה מרוח ומעיניים בלתי רצויות.","ZIP אופקי — התקנה מעל גג זכוכית, הגנה משמש וחום."]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('page', 'services', 'he', 3, 'גגות זכוכית', NULL, '["גג זכוכית קבוע — פתרון יציב למקסימום אור כל השנה.","סקיילייט חשמלי — הגג נפתח ונסגר בלחיצת כפתור, עם שליטה מלאה באוורור."]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('page', 'services', 'he', 4, 'זיגוג', '["מערכת זיגוג מרפסות — מערכת ללא מסגרות. תצפית מקסימלית בזכות זכוכית מחוסמת ובטוחה, ללא פרופילים מיותרים: פאנלי הזכוכית נעים לפינת המרפסת ומתקפלים בשיטת \"ספר\". המבנה מורכב מזכוכית מחוסמת בעובי 8 או 10 מ\"מ — בזכוכית בודדת או בזיגוג כפול. החברה מציעה בסך הכול ארבעה סוגי זיגוג ללא מסגרות בעובי 8–10 מ\"מ, ובמודלים מסוימים נעילת הפאנלים מתבצעת באמצעות מגנט, מה שהופך את הפתיחה והסגירה לחלקה ומרשימה מבחינה חזותית.","סוגי הזיגוג:"]'::jsonb, '["זיגוג ללא מסגרות — פתיחה מלאה בקיפול חלק של פאנלי הזכוכית לצד, בשיטת \"ספר\", ללא פרופילים אנכיים החוסמים את התצפית; נעילת הפאנלים באמצעות מגנט.","זיגוג עם וילונות משולבים — בתוך הזיגוג הכפול מותקנים וילונות ונציאניים הנמצאים בסביבה אטומה לחלוטין — ללא אבק וללא צורך בתחזוקה נפרדת.","חלון גיליוטינה — פתיחה וסגירה אנכית בלחיצת כפתור, ללא עמוד אמצעי, עם אפשרות עצירה בכל גובה."]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('page', 'services', 'he', 5, 'מדוע לבחור בפרגולת אלומיניום', '["אלומיניום הוא החומר המוביל לפרגולות מודרניות, וזו הסיבה:"]'::jsonb, '["עמידות רבה לאורך שנים, ללא חלודה ורקבון.","מבנה חזק ויציב בכל תנאי מזג אוויר.","עיצוב מינימליסטי ונקי עם קווים מדויקים.","תחזוקה מינימלית — ללא צביעה ותחזוקה שוטפת."]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('page', 'services', 'he', 6, 'כיצד מתנהל תהליך ההזמנה', '["מהפנייה ועד ההתקנה — כל שלב מאורגן ומובן:"]'::jsonb, '["פנייה ואיסוף מידע על הצרכים והמידות.","תכנון והצעת מחיר מותאמת אישית.","ייצור לפי מידה במפעל.","התקנה מקצועית בכל רחבי ישראל."]'::jsonb, '["Vitlion Group מתמחה בתכנון, ייצור והתקנה של פרגולות אלומיניום ופתרונות פרימיום להצללה וזיגוג. אנו מציעים מגוון רחב — מפרגולות ביוקלימטיות חשמליות ועד זיגוג ללא מסגרות, תריסי ZIP, גיליוטינות וגגות זכוכית — הכול מאלומיניום איכותי עם עמידות לאורך שנים.","כל פתרון מיוצר לפי מידה ומותאם בדיוק לחלל, לאדריכלות ולסטייל שלכם. אנו עובדים עם חומרים איכותיים, מנועים אמינים וטכנולוגיות מתקדמות, המבטיחים שליטה מלאה באור, בצל, באוויר ובפרטיות — בלחיצת כפתור.","השירות שלנו כולל תכנון, ייצור והתקנה מקצועית בכל רחבי ישראל. קבלו הצעת מחיר מותאמת אישית, ואנו נהפוך את החלל הפתוח שלכם למקום המושלם בכל עונה בשנה."]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('page', 'services', 'ru', 0, 'Электрические перголы', NULL, '["Биоклиматик — ламели одновременно двигаются и поворачиваются, полный контроль света и вентиляции.","Биоклиматик Bio Rolling — ламели только сдвигаются в сторону, крыша открывается полностью.","Биоклиматик Рафафа — ламели только поворачиваются на месте, без сдвига, для тонкой настройки света.","Биоклиматик со стеклянными ламелями — сочетание прозрачности стекла и механики поворотных ламелей.","ПВХ-пергола прямая — гибкая водостойкая крыша прямой формы.","ПВХ-пергола арочная — гибкая водостойкая крыша арочной формы."]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('page', 'services', 'ru', 1, 'Стационарные перголы', NULL, '["Пергола хай-тек с прямыми планками — чистый минималистичный вид.","Пергола хай-тек с декоративными планками по бокам.","Классическая пергола — доступное решение без компромиссов в качестве.","Пергола из теплоизоляционной панели — полная тепло- и звукоизоляция."]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('page', 'services', 'ru', 2, 'ZIP-шторы', NULL, '["ZIP-экраны — вертикальная установка по бокам, защита от ветра и посторонних взглядов.","ZIP горизонтальный — установка над стеклянной крышей, защита от солнца и жары."]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('page', 'services', 'ru', 3, 'Стеклянные крыши', NULL, '["Стационарная стеклянная крыша — устойчивое решение для максимума света круглый год.","Электрический скайлайт — крыша открывается и закрывается нажатием кнопки, полный контроль вентиляции."]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('page', 'services', 'ru', 4, 'Остекление', '["Система остекления балконов — безрамная система. Максимальный обзор благодаря закаленному и безопасному стеклу, без лишних профилей: стеклянные панели сдвигаются в угол балкона, складываясь по принципу книжки. Конструкция собирается из закалённого стекла толщиной 8 или 10 миллиметров — как в виде одиночного стекла, так и в виде двойного стеклопакета. Всего компания предлагает четыре вида безрамного остекления толщиной 8–10 мм, а фиксация панелей в некоторых моделях осуществляется с помощью магнита, что делает открытие и закрытие плавным и визуально очень красивым.","Варианты остекления:"]'::jsonb, '["Безрамное остекление — полное открытие плавным складыванием стеклянных панелей в сторону, по принципу книжки, без вертикальных профилей, мешающих обзору; фиксация панелей через магнит.","Остекление со встроенными жалюзи — внутри стеклопакета установлены венецианские жалюзи, находящиеся в полностью герметичной среде — без пыли и без необходимости отдельного обслуживания.","Окно-гильотина — вертикальное открытие и закрытие нажатием кнопки, без средней стойки, с возможностью остановки на любой высоте."]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('page', 'services', 'ru', 5, 'Почему стоит выбрать алюминиевую перголу', '["Алюминий — ведущий материал для современных пергол, и вот почему:"]'::jsonb, '["Высокая долговечность на годы без ржавчины и гниения.","Прочная и устойчивая конструкция в любую погоду.","Минималистичный чистый дизайн с точными линиями.","Минимальный уход — без покраски и постоянного обслуживания."]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('page', 'services', 'ru', 6, 'Как проходит процесс заказа', '["От обращения до монтажа — каждый этап организован и понятен:"]'::jsonb, '["Обращение и сбор данных о потребностях и размерах.","Проектирование и индивидуальный расчёт.","Производство по размеру на заводе.","Профессиональный монтаж по всему Израилю."]'::jsonb, '["Vitlion Group специализируется на проектировании, производстве и монтаже алюминиевых пергол и премиальных решений для навеса и остекления. Мы предлагаем широкий ассортимент — от электрических биоклиматических пергол до безрамного остекления, ZIP-роллетов, гильотин и стеклянных крыш — всё из качественного алюминия с долговечностью на годы.","Каждое решение производится по размеру и точно подгоняется под ваше пространство, архитектуру и стиль. Мы работаем с качественными материалами, надёжными моторами и передовыми технологиями, обеспечивая полный контроль над светом, тенью, воздухом и приватностью — нажатием кнопки.","Наш сервис включает проектирование, производство и профессиональный монтаж по всему Израилю. Получите индивидуальный расчёт, и мы превратим ваше открытое пространство в идеальное место в любое время года."]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'electric-pergolas', 'he', 0, 'מה זו פרגולה חשמלית מבית Vitlion Group', '["פרגולה חשמלית היא מבנה הצללה מאלומיניום המבוסס על שלבים (למלות) מתכווננים, המופעלים באמצעות מנוע חשמלי. ברוב הדגמים שלנו - קטגוריית הביוקלימטיק - השלבים עשויים אלומיניום ונעים בטווח של 0° עד 90°, כך שניתן לשלוט באופן מדויק בכמות האור, הצל והאוורור הנכנסים לחלל. הפעלת המבנה מתבצעת בשלט רחוק, מתג קיר או אפליקציה סלולרית, ובניגוד לפרגולה קבועה, השלבים מתאימים את עצמם לתנאי מזג האוויר בזמן אמת ולא להיפך."]'::jsonb, NULL, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'electric-pergolas', 'he', 1, 'מאפיינים טכניים מרכזיים:', '["לצד דגמי הביוקלימטיק, הקטגוריה כוללת גם פרגולת PVC - דגם שאינו מבוסס על שלבים מסתובבים אלא על גג יריעה גמיש ועמיד למים, בעיצוב ישר או קשתי, המתאים למקרים בהם נדרשת סגירה מהירה ומלאה מפני גשם."]'::jsonb, '["שלבי אלומיניום מתכווננים בטווח 0°-90° לשליטה מדויקת באור ובצל","פתיחה מלאה של הגג ליצירת תחושת מרחב פתוח לחלוטין","מערכת ניקוז נסתרת מובנית לאטימות מלאה בזמן גשם","שליטה חשמלית בשלט, מתג קיר או אפליקציה","אפשרות חיבור לבית חכם ותאורת LED משולבת"]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'electric-pergolas', 'he', 2, 'סוגי הפרגולות החשמליות - השוואה בין הדגמים', '["בקטגוריית הפרגולות החשמליות של Vitlion Group קיימים חמישה דגמים עיקריים, הנבדלים זה מזה באופן תנועת השלבים:"]'::jsonb, '["ביוקלימטיק - השלבים גם נפתחים ונסגרים (הזזה) וגם מסתובבים (סבסוב), המאפשר שליטה מלאה בו-זמנית באור, בצל ובאוורור.","ביוקלימטיק Bio Rolling - השלבים נעים בהזזה בלבד ונאספים לחלוטין לצד, כך שהגג נפתח לחלוטין ללא שלבים סבסוביים.","ביוקלימטיק רפפה - השלבים מסתובבים במקום בלבד, ללא הזזה, ומיועדים לשליטה עדינה ומדויקת באור מבלי לשנות את גיאומטריית הגג.","ביוקלימטיק עם שלבי זכוכית - שילוב של שלבי זכוכית מחוסמת עם מכניקת הסבסוב הרגילה, המשלב שקיפות אסתטית עם שליטה פונקציונלית.","פרגולת PVC (ישרה או קשתית) - גג יריעה גמיש ועמיד למים, ללא שלבים, מתאים לפתרון מהיר ומלא מפני גשם ורוח."]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'electric-pergolas', 'he', 3, 'כיצד עובדת הפרגולה החשמלית - תהליך הפעלה', '["ההפעלה מתבצעת בארבעה שלבים פשוטים, המתאימים לכל עונה בשנה:"]'::jsonb, '["בלחיצת כפתור אחת פותחים או סוגרים את השלבים.","מכווננים את זווית השלבים (0°-90°) לכמות הצל והאוורור הרצויה.","בזמן גשם, סוגרים את השלבים אטימות מלאה, כאשר מערכת הניקוז המובנית מפנה את המים ללא נזילה.","ניתן להוסיף חיישני רוח וגשם אופציונליים, המפעילים סגירה אוטומטית של השלבים ללא צורך בהתערבות ידנית."]'::jsonb, '["בניגוד לפרגולה קבועה, הפרגולה החשמלית של Vitlion Group מסתגלת לתנאי מזג האוויר המשתנים בישראל: בקיץ ניתן לכוונן את השלבים למקסימום צל ואוורור, ובחורף לסגור אותם אטימות מלאה מפני גשם. כל פרגולה חשמלית מיוצרת לפי מידה במפעל שלנו בישראל, ומותקנת מקצועית בכל רחבי הארץ - במרכז, בצפון ובדרום."]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'electric-pergolas', 'ru', 0, 'Что такое электрическая пергола от Vitlion Group', '["Электрическая пергола — это конструкция для затенения из алюминия, основанная на регулируемых ламелях, приводимых в движение электрическим мотором. В большинстве наших моделей — категория «Биоклиматик» — ламели изготовлены из алюминия и двигаются в диапазоне от 0° до 90°, что позволяет точно контролировать количество света, тени и вентиляции, поступающих в пространство. Управление конструкцией осуществляется пультом дистанционного управления, настенным выключателем или мобильным приложением, и в отличие от стационарной перголы, ламели подстраиваются под погодные условия в реальном времени, а не наоборот."]'::jsonb, NULL, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'electric-pergolas', 'ru', 1, 'Ключевые технические характеристики:', '["Наряду с моделями Биоклиматик, категория включает и ПВХ-перголу — модель, которая не основана на поворотных ламелях, а представляет собой гибкую водостойкую крышу-полотно прямой или арочной формы, подходящую для случаев, когда требуется быстрое и полное закрытие от дождя."]'::jsonb, '["Поворотные алюминиевые ламели в диапазоне 0°–90° для точного контроля света и тени.","Полное открытие крыши, создающее ощущение полностью открытого пространства.","Встроенная скрытая система водоотвода для полной герметичности во время дождя.","Электрическое управление пультом, настенным выключателем или приложением.","Возможность подключения к умному дому и интеграции LED-подсветки."]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'electric-pergolas', 'ru', 2, 'Виды электрических пергол — сравнение моделей', '["В категории электрических пергол Vitlion Group представлено пять основных моделей, различающихся способом движения ламелей:"]'::jsonb, '["Биоклиматик — ламели одновременно сдвигаются (горизонтальное движение) и поворачиваются (ротация), что обеспечивает одновременный полный контроль света, тени и вентиляции.","Биоклиматик Bio Rolling — ламели двигаются только сдвигом и полностью убираются в сторону, благодаря чему крыша открывается полностью без поворотных ламелей.","Биоклиматик Рафафа — ламели поворачиваются только на месте, без сдвига, и предназначены для тонкой и точной настройки света без изменения геометрии крыши.","Биоклиматик со стеклянными ламелями — сочетание закалённых стеклянных ламелей с обычной механикой ротации, объединяющее эстетическую прозрачность с функциональным контролем.","ПВХ-пергола (прямая или арочная) — гибкая водостойкая крыша-полотно без ламелей, подходящая для быстрого и полного решения от дождя и ветра."]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'electric-pergolas', 'ru', 3, 'Как работает электрическая пергола — процесс управления', '["Управление осуществляется в четыре простых шага, подходящих для любого сезона:"]'::jsonb, '["Одним нажатием кнопки открываются или закрываются ламели.","Регулируется угол ламелей (0°–90°) под нужное количество тени и вентиляции.","Во время дождя ламели закрываются полностью герметично, а встроенная система водоотвода отводит воду без протечек.","Можно добавить опциональные датчики ветра и дождя, которые автоматически закрывают ламели без необходимости ручного управления."]'::jsonb, '["В отличие от стационарной перголы, электрическая пергола Vitlion Group адаптируется к переменчивым погодным условиям в Израиле: летом ламели настраиваются на максимальную тень и вентиляцию, а зимой полностью закрываются для герметичной защиты от дождя. Каждая электрическая пергола производится по индивидуальным размерам на нашем заводе в Израиле и профессионально устанавливается по всей стране — в центре, на севере и на юге."]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'static-pergolas', 'he', 0, 'מה כוללת פרגולה קבועה מבית Vitlion Group', '["פרגולה קבועה היא פתרון הצללה מאלומיניום המבוסס על שלד תמיכה קשיח ומערכת שלבים סטטית, המתאים לחצר, לגינה ולמרפסת ואינו דורש חיבור חשמלי או מנוע. שלד הפרגולה עשוי פרופיל אלומיניום איכותי, ובדגמי ההייטק והקלאסי הקירוי מבוסס על לוחות פוליקרבונט בשם המסחרי סנטף BH, המעוצבים במבנה כוורת דבש ועמידים לרוחות, לברד ולקרינת שמש ישירה."]'::jsonb, NULL, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'static-pergolas', 'he', 1, 'מאפיינים טכניים מרכזיים:', NULL, '["שלד (מבנה תמיכה) מאלומיניום איכותי - חזק ויציב לאורך שנים","מערכת שלבים קבועים בדגמי ההייטק והקלאסי, ליצירת משחק אור וצל מדויק וקבוע","קירוי סנטף BH - לוחות פוליקרבונט עמידים לרוחות, ברד וקרינת שמש","עיצוב הייטק עם פסי צד דקורטיביים, או עיצוב קלאסי חלק וללא תוספות","ייצור לפי מידה, בכל גוון ממניפת RAL"]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'static-pergolas', 'he', 2, 'סוגי הפרגולות הקבועות - השוואה בין הדגמים', '["בקטגוריית הפרגולות הקבועות של Vitlion Group קיימים ארבעה דגמים עיקריים, הנבדלים זה מזה בעיצוב השלבים ובחומר הקירוי:"]'::jsonb, '["פרגולה הייטק פס ישר - שלבים ישרים ונקיים, ללא תוספות עיצוביות, למראה מינימליסטי ומודרני.","פרגולה הייטק פסים מעוצבים - שלבים עם פסי צד דקורטיביים, המוסיפים אופי אדריכלי לחצר.","פרגולה קלאסית - שלד וקירוי בסיסיים ואיכותיים, פתרון משתלם המתאים לתקציב מתון מבלי לפגוע באיכות המבנה.","פרגולה מפנל מבודד - קירוי מפאנל סנדוויץ'' במקום לוחות פוליקרבונט, המספק בידוד תרמי ואקוסטי מלא ומתאים לחללים הדורשים שליטה בטמפרטורה וברעש."]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'static-pergolas', 'he', 3, 'קירוי סנטף BH - המפרט הטכני', '["קירוי סנטף BH הוא המרכיב המייחד את הפרגולות הקבועות בדגמי ההייטק והקלאסי, ומורכב מלוחות פוליקרבונט גליים במבנה כוורת דבש (Honeycomb), המספקים מספר יתרונות מדידים:"]'::jsonb, '["רמת העברת האור נעה בין 20% ל-87%, בהתאם לגוון הלוח הנבחר.","גוונים מחזירי חום זמינים במגוון צבעים, מותאמים במיוחד לתנאי האקלים החם של ישראל.","המבנה הגלי מסייע בהפחתת רעש נקישות הגשם על הקירוי בהשוואה ללוח שטוח.","הלוחות עמידים לרוחות עונתיות ולברד, ומיוצרים לפי מידה בכל גוון ממניפת RAL, כולל שחור מט ואנתרציט."]'::jsonb, '["הפרגולה הקבועה של Vitlion Group היא פתרון \"גג מעל הראש\" יציב, אמין ועמיד לשנים, ללא צורך בתחזוקה שוטפת או בצביעה חוזרת. ניתן לשלב אותה עם תריסי ZIP להגנה מהצדדים, סגירת זכוכית לשימוש בכל עונות השנה, תאורת LED ו/או גופי חימום אינפרא-אדום. כל הפרגולות מיוצרות במפעל שלנו בישראל ומותקנות מקצועית בכל רחבי הארץ - במרכז, בצפון ובדרום."]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'static-pergolas', 'ru', 0, 'Что включает стационарная пергола от Vitlion Group', '["Стационарная пергола — это решение для затенения из алюминия, основанное на жёстком опорном каркасе и статичной системе ламелей, подходящее для двора, сада и террасы и не требующее подключения к электричеству или мотора. Каркас перголы изготовлен из качественного алюминиевого профиля, а в моделях хай-тек и классика кровля выполнена из поликарбонатных панелей под торговой маркой Сантеф BH, имеющих сотовую (Honeycomb) структуру и устойчивых к ветру, граду и прямому солнечному излучению."]'::jsonb, NULL, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'static-pergolas', 'ru', 1, 'Ключевые технические характеристики:', NULL, '["Каркас (опорная конструкция) из качественного алюминия — прочный и устойчивый на протяжении многих лет.","Система фиксированных ламелей в моделях хай-тек и классика, создающая точную и постоянную игру света и тени.","Кровля Сантеф BH — поликарбонатные листы, устойчивые к ветру, граду и солнечному излучению.","Дизайн хай-тек с декоративными боковыми планками, либо гладкий классический дизайн без дополнительных элементов.","Производство по индивидуальным размерам, в любом цвете палитры RAL."]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'static-pergolas', 'ru', 2, 'Виды стационарных пергол — сравнение моделей', '["В категории стационарных пергол Vitlion Group представлено четыре основных модели, различающихся дизайном ламелей и материалом кровли:"]'::jsonb, '["Пергола хай-тек с прямыми планками — прямые, чистые ламели без декоративных элементов, для минималистичного и современного вида.","Пергола хай-тек с декоративными планками — ламели с боковыми декоративными планками, добавляющими архитектурный характер двору.","Классическая пергола — базовый каркас и кровля хорошего качества, доступное решение для умеренного бюджета без потери качества конструкции.","Пергола из теплоизоляционной панели — кровля из сэндвич-панели вместо поликарбонатных листов, обеспечивающая полную тепло- и звукоизоляцию, подходит для пространств, где важен контроль температуры и шума."]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'static-pergolas', 'ru', 3, 'Кровля Сантеф BH — технические параметры', '["Кровля Сантеф BH — это компонент, отличающий стационарные перголы в моделях хай-тек и классика, состоящий из волнистых поликарбонатных листов сотовой структуры (Honeycomb), которые обеспечивают несколько измеримых преимуществ:"]'::jsonb, '["Уровень светопропускания варьируется от 20% до 87% в зависимости от выбранного оттенка панели.","Теплоотражающие оттенки доступны в разных цветах, специально адаптированных к жаркому климату Израиля.","Волнистая структура помогает снизить шум от ударов дождевых капель по кровле по сравнению с плоским листом.","Панели устойчивы к сезонным ветрам и граду, производятся по индивидуальным размерам в любом цвете палитры RAL, включая чёрный матовый и антрацит."]'::jsonb, '["Стационарная пергола Vitlion Group — это надёжное и долговечное решение «крыша над головой», не требующее регулярного обслуживания или повторной окраски. Её можно дополнить ZIP-роллетами для боковой защиты, стеклянным остеклением для использования в любое время года, LED-подсветкой и/или инфракрасными обогревателями. Все перголы производятся на нашем заводе в Израиле и профессионально устанавливаются по всей стране — в центре, на севере и на юге."]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'zip-shutters', 'he', 0, 'תריסי ZIP — פתרון הצללה וסגירה מתקדם', NULL, NULL, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'zip-shutters', 'he', 1, 'מה מייחד תריסי ZIP', '["פתרון הצללה וסגירה מתקדם עם טכנולוגיית בד מתוח: בד PVC ייעודי הננעל במסילות ונשאר מתוח באופן אחיד, הגנה מלאה משמש, חום, רוח, אבק וחרקים, ללא שקיעות וללא חדירת אור מהצדדים, שליטה חשמלית בשלט, מתג קיר או אפליקציה, עיצוב מינימליסטי נקי בכל מזג אוויר."]'::jsonb, NULL, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'zip-shutters', 'he', 2, 'סוגי תריסי ה‑ZIP שלנו', '["שני דגמים לפי מיקום ההתקנה:"]'::jsonb, '["מסכי ZIP — התקנה אנכית לצדדים, הגנה מרוח ומבטים.","ZIP אופקי — התקנה מתחת לגג זכוכית, הגנה משמש וחום."]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'zip-shutters', 'he', 3, 'איך זה עובד', '["הפעלה פשוטה ושליטה מדויקת: בלחיצת כפתור הבד יורד או עולה במסילות, עצירה בכל נקודה לשליטה בעוצמת האור, הבד נשאר מתוח ואטום מהצדדים, אפשרות לחיבור לבית חכם."]'::jsonb, NULL, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'zip-shutters', 'he', 4, 'תיאור מלא', '["תריסי ZIP הם פתרון מודרני להגנה על המרחב מפני שמש, רוח, אבק ומבטים מבחוץ. בניגוד לסוכך רגיל, בד ה‑ZIP ננעל במסילות בצדדים ונשאר מתוח באופן אחיד — ללא התנפחות ברוח וללא חדירת אור מהצדדים. אנחנו מציעים שני דגמים: מסכי ZIP להתקנה אנכית בצדדי הפרגולה או המרפסת, ו‑ZIP אופקי להתקנה מתחת לגג זכוכית להגנה מפני שמש וחום. הבד עשוי PVC ייעודי החוסם קרינה ומפחית התחממות, ומגיע במגוון גוונים. השליטה חשמלית לחלוטין — בשלט, במתג קיר או דרך אפליקציה, עם אפשרות לעצירה בכל גובה ולחיבור למערכת בית חכם. תריסי ZIP מתאימים לפרגולות, מרפסות, טרסות וחללים מסחריים. ייצור לפי מידה והתקנה מקצועית בכל הארץ."]'::jsonb, NULL, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'zip-shutters', 'ru', 0, 'ZIP‑роллеты — продвинутое решение для затенения и закрытия пространства', NULL, NULL, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'zip-shutters', 'ru', 1, 'Что отличает ZIP‑роллеты', '["Продвинутое решение для затенения и закрытия с технологией натянутой ткани: специальное PVC‑полотно фиксируется в направляющих и остаётся равномерно натянутым, полная защита от солнца, жары, ветра, пыли и насекомых, отсутствие провисаний и боковых засветов, электрическое управление пультом, настенным выключателем или приложением, минималистичный чистый дизайн в любую погоду."]'::jsonb, NULL, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'zip-shutters', 'ru', 2, 'Виды наших ZIP‑роллет', '["Две модели по месту установки:"]'::jsonb, '["ZIP‑экраны — вертикальная установка по бокам, защита от ветра и посторонних взглядов.","Горизонтальный ZIP — установка под стеклянной крышей, защита от солнца и жары."]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'zip-shutters', 'ru', 3, 'Как это работает', '["Простое управление и точный контроль: одним нажатием кнопки ткань опускается или поднимается по направляющим, остановка в любой точке для регулировки интенсивности света, ткань остаётся натянутой и герметичной по бокам, есть возможность подключения к умному дому."]'::jsonb, NULL, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'zip-shutters', 'ru', 4, 'Полное описание', '["ZIP‑роллеты — современное решение для защиты пространства от солнца, ветра, пыли и посторонних взглядов. В отличие от обычного навеса, полотно ZIP фиксируется в боковых направляющих и остаётся равномерно натянутым — без раздувания на ветру и без проникновения света по краям. Мы предлагаем две модели: ZIP‑экраны для вертикальной установки по бокам перголы или балкона, и горизонтальный ZIP для установки под стеклянной крышей для защиты от солнца и жары. Полотно изготовлено из специального PVC‑материала, блокирующего излучение и снижающего нагрев, доступно в разных оттенках. Управление полностью электрическое — пультом, настенным выключателем или через приложение, с возможностью остановки на любой высоте и подключения к системе умного дома. ZIP‑роллеты подходят для пергол, балконов, террас и коммерческих пространств. Производство по индивидуальным размерам и профессиональная установка по всей стране."]'::jsonb, NULL, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'glass-roofs', 'he', 0, 'גגות זכוכית — פתרון אדריכלי יוקרתי', NULL, NULL, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'glass-roofs', 'he', 1, 'מה כוללים גגות הזכוכית שלנו', '["פתרון אדריכלי יוקרתי שפותח את השמיים ומרחיב את גבולות החלל:"]'::jsonb, '["אור טבעי מקסימלי וחיסכון בתאורה מלאכותית","חיבור מושלם בין פנים לחוץ","זכוכית מחוסמת או בידודית לפי הצורך","שלד אלומיניום עמיד עם צביעה בתנור","אפשרות לשילוב עם תריסי ZIP או מערכות סגירה"]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'glass-roofs', 'he', 2, 'הדגמים שלנו', '["שני פתרונות לפי מידת השליטה הרצויה:"]'::jsonb, '["גג זכוכית קבוע — פתרון יציב לאור טבעי מקסימלי לאורך כל השנה.","סקיילייט חשמלי — גג זכוכית נפתח ונסגר בלחיצת כפתור, עם שליטה מלאה באוורור."]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'glass-roofs', 'he', 3, 'למי זה מתאים', '["פתרון אידיאלי למגוון חללים:"]'::jsonb, '["בתים פרטיים ווילות — מרפסות, גינות חורף, אזורי בריכה","מסעדות ובתי קפה — יצירת חלל פתוח לאורך כל השנה","חללים עסקיים — לובאים ואזורי לאונג''","פרויקטים מסחריים — גלריות ושואורומים"]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'glass-roofs', 'he', 4, 'תיאור מלא', '["גגות זכוכית הם פתרון אדריכלי יוקרתי שפותח את השמיים ומרחיב את גבולות החלל. הם ממלאים את הסביבה באור טבעי, תחושת קלילות ואווירה של מרחב פתוח — תוך חיבור מושלם בין פנים לחוץ. אנחנו מציעים שני דגמים: גג זכוכית קבוע לפתרון יציב ואמין לאורך כל השנה, וסקיילייט חשמלי המאפשר פתיחה וסגירה בלחיצת כפתור לשליטה מלאה באוורור ובטמפרטורה. שני הדגמים בנויים משלד אלומיניום עמיד עם צביעה בתנור בכל גוון RAL. גג זכוכית מאפשר חדירה מקסימלית של אור יום, מפחית את הצורך בתאורה מלאכותית ותורם לחיסכון בצריכת החשמל. אפשר לשלב תריסי ZIP או מערכות סגירה להגנה נוספת מהשמש. מתאים לבתים פרטיים, וילות, מסעדות, בתי קפה וחללים מסחריים. ייצור לפי מידה והתקנה מקצועית בכל הארץ."]'::jsonb, NULL, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'glass-roofs', 'ru', 0, 'Стеклянные крыши — роскошное архитектурное решение', NULL, NULL, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'glass-roofs', 'ru', 1, 'Что включают наши стеклянные крыши', '["Роскошное архитектурное решение, открывающее небо и расширяющее границы пространства:"]'::jsonb, '["Максимум естественного света и экономия на искусственном освещении","Идеальная связь между внутренним и внешним пространством","Закалённое или изолирующее стекло по необходимости","Прочный алюминиевый каркас с печной окраской","Возможность сочетания с ZIP‑роллетами или другими системами закрытия"]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'glass-roofs', 'ru', 2, 'Наши модели', '["Два решения в зависимости от нужной степени контроля:"]'::jsonb, '["Стационарная стеклянная крыша — стабильное решение для максимального естественного света в течение всего года.","Электрический скайлайт — стеклянная крыша, открывающаяся и закрывающаяся нажатием кнопки, с полным контролем вентиляции."]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'glass-roofs', 'ru', 3, 'Кому подходит', '["Идеальное решение для разных пространств:"]'::jsonb, '["Частные дома и виллы — террасы, зимние сады, зоны у бассейна","Рестораны и кафе — создание открытого пространства в течение всего года","Деловые пространства — лобби и лаунж‑зоны","Коммерческие проекты — галереи и шоурумы"]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'glass-roofs', 'ru', 4, 'Полное описание', '["Стеклянные крыши — роскошное архитектурное решение, открывающее небо и расширяющее границы пространства. Они наполняют окружение естественным светом, ощущением легкости и атмосферой открытого пространства, обеспечивая идеальную связь между внутренним и внешним пространством. Мы предлагаем две модели: стационарную стеклянную крышу — стабильное и надёжное решение на весь год, и электрический скайлайт, позволяющий открывать и закрывать крышу нажатием кнопки для полного контроля вентиляции и температуры. Обе модели построены на прочном алюминиевом каркасе с печной окраской в любом оттенке RAL. Стеклянная крыша обеспечивает максимальное проникновение дневного света, снижает потребность в искусственном освещении и способствует экономии электроэнергии. Можно добавить ZIP‑роллеты или другие системы закрытия для дополнительной защиты от солнца. Подходит для частных домов, вилл, ресторанов, кафе и коммерческих пространств. Производство по индивидуальным размерам и профессиональная установка по всей стране."]'::jsonb, NULL, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'glazing', 'he', 0, 'מערכת זכוכיות נאספות — פתרון סגירה יוקרתי', NULL, NULL, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'glazing', 'he', 1, 'מה כוללת מערכת הזכוכיות הנאספות', '["פתרון סגירה יוקרתי שמכניס את החוץ פנימה:"]'::jsonb, '["זכוכית היא הכוכבת — הפרופילים כמעט נעלמים","פתיחה מלאה בקיפול חלק לצד","זכוכית מחוסמת חזקה ובטיחותית","הגנה מפני רוח, גשם ורעש","מינימום מסגרות, מקסימום נוף וחופש"]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'glazing', 'he', 2, 'הדגמים שלנו', '["פתרונות זכוכית מתקדמים לכל צורך:"]'::jsonb, '["זכוכיות נאספות — פתיחה מלאה לצד; זכוכית בודדת מחוסמת בעובי 8 מ\"מ או 10 מ\"מ.","זכוכיות נאספות עם צלון כלוא — תריס ונציאני מובנה בתוך זכוכית בידודית (4 מ\"מ + חלל אוויר 22 מ\"מ + 4 מ\"מ), סביבה אטומה לחלוטין וללא תחזוקה.","גיליוטינה — פתיחה וסגירה אנכית בלחיצת כפתור, ללא עמוד ביניים.","זכוכית בידודית מחוסמת לבידוד תרמי ואקוסטי — מבנה של 4 מ\"מ + חלל אוויר 22 מ\"מ + 4 מ\"מ, ללא צלונים.","אפשרות לשליטה ידנית, חשמלית, ובחלק מהדגמים — נעילה מגנטית לתנועה חלקה."]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'glazing', 'he', 3, 'גיליוטינה — פתיחה אנכית חכמה', '["לצד הזכוכיות הנאספות, אנחנו מציעים גם חלון גיליוטינה:"]'::jsonb, '["פתיחה וסגירה אנכית — למעלה ולמטה — בלחיצת כפתור","עיצוב נקי ללא עמוד ביניים","זכוכית מחוסמת חזקה ובטיחותית","עצירה בכל גובה לפי הצורך","מתאים למרפסות, מסעדות ובתי קפה"]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'glazing', 'he', 4, 'למי זה מתאים', '["פתרון אידיאלי למגוון חללים:"]'::jsonb, '["מרפסות וטרסות בבתים פרטיים ובדירות","גינות חורף וחזיתות","מסעדות ובתי קפה — חלל פתוח לאורך כל השנה","חללים מסחריים ושואורומים"]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'glazing', 'he', 5, 'תיאור מלא', '["מערכת הזיגוג באמצעות זכוכיות נאספות נולדה עבור מי שלא מוכן להתפשר — לא על עיצוב, לא על נוחות ולא על תחושת המרחב. הזכוכית היא הכוכבת, והפרופילים כמעט נעלמים, כך שנשאר רק נוף נקי, פתוח ומרשים. בתנועה חלקה (בחלק מהדגמים בעזרת נעילה מגנטית), המערכת מתקפלת ונאספת לצד ופותחת את החלל לחלוטין. רוצים להרגיש את האוויר? הכול פתוח. צריכים הגנה? סוגרים — והמרחב נשאר מואר, שקט ומוגן. הזכוכית מחוסמת, חזקה ובטיחותית, ומגינה מפני רוח, גשם ורעש. קיים גם דגם מתקדם עם צלון כלוא — תריס ונציאני מובנה בתוך הזכוכית (זכוכית בידודית 4+22+4 מ\"מ), בסביבה אטומה לחלוטין, ללא אבק וללא צורך בתחזוקה.","לצד הזכוכיות הנאספות, אנחנו מציעים גם חלון גיליוטינה — מערכת זכוכית עם תנועה אנכית חלקה, הנפתחת והנסגרת למעלה ולמטה בלחיצת כפתור. שני הפתרונות משלבים עיצוב מינימליסטי עם הנדסה מדויקת ומתאימים למרפסות, טרסות, גינות חורף, מסעדות וחללים מסחריים. ייצור לפי מידה והתקנה מקצועית בכל הארץ."]'::jsonb, NULL, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'glazing', 'ru', 0, 'Система раздвижного остекления — роскошное решение для закрытия пространства', NULL, NULL, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'glazing', 'ru', 1, 'Что включает система раздвижного остекления', '["Роскошное решение, вносящее внешнее пространство внутрь:"]'::jsonb, '["Стекло — главный герой, профили практически исчезают","Полное открытие плавным складыванием в сторону","Прочное и безопасное закалённое стекло","Защита от ветра, дождя и шума","Минимум рамочных конструкций, максимум обзора и свободы"]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'glazing', 'ru', 2, 'Наши модели', '["Продвинутые стеклянные решения для любых задач:"]'::jsonb, '["Раздвижное остекление — полное открытие в сторону; одинарное закалённое стекло толщиной 8 мм или 10 мм.","Раздвижное остекление со встроенными жалюзи — венецианские жалюзи внутри изолирующего стеклопакета (4 мм + воздушный зазор 22 мм + 4 мм), полностью герметичная среда без необходимости обслуживания.","Гильотина — вертикальное открытие и закрытие нажатием кнопки, без промежуточной стойки.","Изолирующее закалённое стекло для тепло‑ и акустической изоляции — конструкция 4 мм + воздушный зазор 22 мм + 4 мм, без жалюзи.","Возможность ручного или электрического управления, в отдельных моделях — магнитная фиксация для плавного перемещения."]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'glazing', 'ru', 3, 'Гильотина — умное вертикальное открытие', '["Помимо раздвижного остекления, мы предлагаем окно‑гильотину:"]'::jsonb, '["Вертикальное открытие и закрытие — вверх и вниз — нажатием кнопки","Чистый дизайн без промежуточной стойки","Прочное и безопасное закалённое стекло","Остановка на любой высоте по необходимости","Подходит для балконов, ресторанов и кафе"]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'glazing', 'ru', 4, 'Кому подходит', '["Идеальное решение для разных пространств:"]'::jsonb, '["Балконы и террасы в частных домах и квартирах","Зимние сады и фасады","Рестораны и кафе — открытое пространство в течение всего года","Коммерческие пространства и шоурумы"]'::jsonb, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('category', 'glazing', 'ru', 5, 'Полное описание', '["Система остекления с раздвижными стёклами создана для тех, кто не готов идти на компромисс — ни в дизайне, ни в комфорте, ни в ощущении пространства. Стекло — главный герой, а профили практически исчезают, оставляя лишь чистый, открытый и впечатляющий вид. Плавным движением (в некоторых моделях — с помощью магнитной фиксации) система складывается и собирается в сторону, полностью открывая пространство. Хочется почувствовать воздух? Всё открыто. Нужна защита? Закрываете — и пространство остаётся светлым, тихим и защищённым. Стекло закалённое, прочное и безопасное, защищает от ветра, дождя и шума. Есть также продвинутая модель со встроенными жалюзи — венецианские жалюзи внутри изолирующего стеклопакета (4+22+4 мм), в полностью герметичной среде, без пыли и необходимости обслуживания.","Помимо раздвижного остекления, мы предлагаем окно‑гильотину — стеклянную систему с плавным вертикальным движением, открывающуюся и закрывающуюся вверх и вниз нажатием кнопки. Оба решения сочетают минималистичный дизайн с точной инженерией и подходят для балконов, террас, зимних садов, ресторанов и коммерческих пространств. Производство по индивидуальным размерам и профессиональная установка по всей стране."]'::jsonb, NULL, NULL);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('model', 'bio-rolling', 'he', 0, 'ביוקלימטיק Bio Rolling - פרגולה חשמלית עם לוחות נגללים', '["ביוקלימטיק Bio Rolling הוא דגם ייחודי בקטגוריית הפרגולות החשמליות של Vitlion Group, המבוסס על לוחות נגללים במקום שלבים מסתובבים. בלחיצת כפתור אחת, הלוחות נגללים ליצירת צל מלא, או נפתחים לחלוטין לחשיפה מקסימלית לאוויר ולשמש."]'::jsonb, '["מתאים במיוחד למבנים ולגגות עם מגבלות גובה, בשל מכניקת הגלילה הקומפקטית","גמישות מרבית - שליטה מדויקת בכמות האור והצל בכל רגע נתון","הפעלה חשמלית פשוטה בלחיצת כפתור, ללא צורך במאמץ פיזי","מתאים לחצרות, מרפסות וחללים מסחריים הדורשים פתרון הצללה קומפקטי ויעיל"]'::jsonb, '["מאפיינים מרכזיים:"]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('model', 'bio-rolling', 'ru', 0, 'Биоклиматик Bio Rolling — электрическая пергола со сворачивающимися панелями', '["Биоклиматик Bio Rolling — это уникальная модель в категории электрических пергол Vitlion Group, основанная на сворачивающихся панелях вместо поворотных ламелей. Одним нажатием кнопки панели сворачиваются, создавая полную тень, либо полностью раскрываются для максимального доступа воздуха и солнечного света."]'::jsonb, '["Особенно подходит для конструкций и крыш с ограничениями по высоте, благодаря компактной механике сворачивания.","Максимальная гибкость — точный контроль количества света и тени в любой момент времени.","Простое электрическое управление одним нажатием кнопки, без физических усилий.","Подходит для дворов, террас и коммерческих пространств, где требуется компактное и эффективное решение затенения."]'::jsonb, '["Ключевые особенности:"]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('model', 'bioclimatic', 'he', 0, 'ביוקלימטיק - הדגם המתקדם בקטגוריית הפרגולות החשמליות', '["פרגולה ביוקלימטית היא פתרון מהפכני לאלה שמעריכים נוחות וטכנולוגיה מודרנית. השלבים - למלות אלומיניום ממונעות - גם נפתחים ונסגרים בהזזה וגם מסתובבים בטווח של 0° עד 90°, לשליטה מלאה בו-זמנית באור, בצל ובאוורור. השליטה מתבצעת מרחוק באמצעות שלט, מתג קיר, או דרך אפליקציה בסמארטפון, המאפשרת כיוונון מדויק של השלבים מכל מקום.","מאפיינים טכניים מרכזיים:"]'::jsonb, '["שלבי אלומיניום ממונעים, הנעים בהזזה ובסבסוב בו-זמנית (0°-90°), לשליטה מלאה באור ובאוורור","שליטה מרחוק בשלט, מתג קיר, או דרך אפליקציה בסמארטפון","מערכת ניקוז נסתרת מובנית לאטימות מלאה בזמן גשם","חיישני רוח וגשם אופציונליים, לסגירה אוטומטית של השלבים בעת שינוי מזג אוויר","זמינות אינטגרציה עם מערכת בית חכם, כולל אפשרות לתאורת LED משולבת","ייצור לפי מידות אישיות, בכל גוון ממניפת RAL"]'::jsonb, '["היתרון המרכזי של הדגם הוא השילוב בין נוחות תפעולית לגמישות: ניתן לכוונן את השלבים בדיוק לכמות האור והצל הרצויה, ובעת הצורך להוסיף חיישני רוח וגשם שיסגרו את הגג באופן אוטומטי גם כשאין אף אחד בבית להפעיל את הפרגולה באופן ידני. יחד עם האפשרות לחיבור לבית חכם, ניתן לשלב את הפרגולה בשגרת הבית ולתזמן פתיחה וסגירה. כל פרגולה מיוצרת לפי מידה במפעל שלנו בישראל ומותקנת מקצועית בכל רחבי הארץ - במרכז, בצפון ובדרום"]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('model', 'bioclimatic', 'ru', 0, 'Биоклиматик — продвинутая модель в категории электрических пергол', '["Биоклиматическая пергола — это революционное решение для тех, кто ценит комфорт и современные технологии. Ламели — моторизированные алюминиевые планки — одновременно сдвигаются в сторону и поворачиваются в диапазоне от 0° до 90°, обеспечивая полный одновременный контроль света, тени и вентиляции. Управление осуществляется дистанционно с помощью пульта, настенного выключателя, либо через приложение на смартфоне, позволяющее точно настраивать положение ламелей из любой точки.","Ключевые технические характеристики:"]'::jsonb, '["Моторизированные алюминиевые ламели, двигающиеся сдвигом и поворотом одновременно (0°–90°), для полного контроля света и вентиляции.","Дистанционное управление пультом, настенным выключателем или через приложение на смартфоне.","Встроенная скрытая система водоотвода для полной герметичности во время дождя.","Опциональные датчики ветра и дождя для автоматического закрытия ламелей при изменении погоды.","Доступна интеграция с системой умного дома, включая опцию встроенной LED-подсветки.","Производство по индивидуальным размерам, в любом цвете палитры RAL."]'::jsonb, '["Главное преимущество модели — сочетание эксплуатационного комфорта и гибкости: ламели можно точно настроить на нужное количество света и тени, а при необходимости добавить датчики ветра и дождя, которые автоматически закроют крышу при смене погоды, даже если дома никого нет, чтобы управлять перголой вручную. Вместе с возможностью подключения к умному дому, перголу можно встроить в общий распорядок дома и настроить график открытия и закрытия. Каждая пергола производится по индивидуальным размерам на нашем заводе в Израиле и профессионально устанавливается по всей стране — в центре, на севере и на юге."]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('model', 'shlavey-zhuhit', 'he', 0, 'ביוקלימטיק שלבי זכוכית - שקיפות מקסימלית עם שליטה מלאה', '["ביוקלימטיק שלבי זכוכית הוא הפתרון המושלם למי שרוצה ליהנות מאור טבעי מקסימלי בו-זמנית עם שליטה מלאה על האוורור. בדגם זה, שלבי הזכוכית המחוסמת מחליפים את שלבי האלומיניום הרגילים, אך פועלים על אותה מכניקת סבסוב מ-0° עד 90° הקיימת בשאר דגמי הביוקלימטיק. כאשר השלבים סגורים, לוחות הזכוכית מאפשרים מעבר אור טבעי מלא; כאשר הם פתוחים, נוצר אוורור מעולה עם שליטה מדויקת בזרימת האוויר.","מאפיינים טכניים מרכזיים:"]'::jsonb, '["שלבי זכוכית מחוסמת, הנעים בסבסוב בטווח 0°-90°, כמו בשאר דגמי הביוקלימטיק","מעבר אור טבעי מלא במצב סגור, ואוורור מעולה במצב פתוח","שילוב של שקיפות אסתטית עם שליטה פונקציונלית מדויקת","אידיאלי לגגות וטרסות בהן חשוב לשמור על מראה אדריכלי בנוי ואחיד","שליטה חשמלית בשלט, מתג קיר או אפליקציה, עם אפשרות לחיישני רוח וגשם אופציונליים ולחיבור לבית חכם","ייצור לפי מידה, שלד אלומיניום עמיד בכל גוון RAL"]'::jsonb, '["הדגם מתאים במיוחד לחללים בהם מראה אדריכלי אחיד וקו עיצובי נקי חשובים לא פחות מהתפקוד - השילוב בין זכוכית מחוסמת לשלד אלומיניום יוצר מבנה שנראה מגובש כל השנה, בין אם הוא סגור לחלוטין או פתוח לאוורור מלא. כל פרגולה מיוצרת לפי מידה במפעל שלנו בישראל ומותקנת מקצועית בכל רחבי הארץ - במרכז, בצפון ובדרום."]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('model', 'shlavey-zhuhit', 'ru', 0, 'Биоклиматик со стеклянными ламелями — максимальная прозрачность с полным контролем', '["Биоклиматик со стеклянными ламелями — идеальное решение для тех, кто хочет одновременно наслаждаться максимальным естественным светом и иметь полный контроль над вентиляцией. В этой модели закалённые стеклянные ламели заменяют обычные алюминиевые, но работают по той же механике поворота в диапазоне от 0° до 90°, что и в остальных моделях биоклиматических пергол. Когда ламели закрыты, стеклянные панели обеспечивают полный проход естественного света; когда они открыты, создаётся отличная вентиляция с точным контролем потока воздуха.","Ключевые технические характеристики:"]'::jsonb, '["Ламели из закалённого стекла, двигающиеся поворотом в диапазоне 0°–90°, как и в остальных моделях биоклиматика.","Полный проход естественного света в закрытом положении и отличная вентиляция в открытом.","Сочетание эстетической прозрачности с точным функциональным контролем.","Идеально подходит для крыш и террас, где важно сохранить единый и цельный архитектурный облик.","Электрическое управление пультом, настенным выключателем или приложением, с возможностью установки опциональных датчиков ветра и дождя и подключения к умному дому.","Производство по индивидуальным размерам, прочный алюминиевый каркас в любом цвете RAL."]'::jsonb, '["Модель особенно подходит для пространств, где единый архитектурный облик и чистая дизайнерская линия важны не менее функциональности — сочетание закалённого стекла с алюминиевым каркасом создаёт конструкцию, выглядящую цельной в течение всего года, независимо от того, полностью ли она закрыта или полностью открыта для вентиляции. Каждая пергола производится по индивидуальным размерам на нашем заводе в Израиле и профессионально устанавливается по всей стране — в центре, на севере и на юге."]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('model', 'pvc-kshatit', 'he', 0, 'פרגולת PVC קשתית - עיצוב אלגנטי עם ביצועים מוכחים', '["פרגולת PVC קשתית היא גרסה אלגנטית של פרגולת ה-PVC, המבוססת על גג יריעה גמיש ועמיד למים, אך בצורה קשתית ייחודית במקום הצורה הישרה הרגילה. הצורה הקשתית מעניקה לחלל מראה יוקרתי ואדריכלי, ומתאימה במיוחד למי שמחפש פתרון הצללה שמשלב אסתטיקה בולטת עם פונקציונליות מלאה.","מאפיינים טכניים מרכזיים:"]'::jsonb, '["גג יריעה גמיש בצורה קשתית, עמיד למים ולתנאי מזג האוויר הישראלי","הגנה מלאה מהשמש ומהגשם, עם סגירה מהירה בעת הצורך","בד ה-PVC עמיד בפני קרינת UV ואינו מצהיב עם הזמן","שליטה חשמלית פשוטה, כמו בדגם הפרגולה הישרה","מראה אדריכלי ייחודי, מתאים לחללים בהם העיצוב הוא שיקול מרכזי"]'::jsonb, '["כמו פרגולת ה-PVC הרגילה, גם הגרסה הקשתית עמידה לתנאי מזג האוויר הישראלי - חמסינים, רוחות עונתיות וגשם - ומספקת הגנה מהירה ומלאה בלחיצת כפתור. ההבדל המרכזי הוא בקו העיצובי: הצורה הקשתית מוסיפה רכות ותחכום ויזואלי, בהשוואה לקו הישר והמינימליסטי של הדגם הרגיל. הפרגולה מיוצרת לפי מידה במפעל שלנו בישראל ומותקנת מקצועית בכל רחבי הארץ - במרכז, בצפון ובדרום."]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('model', 'pvc-kshatit', 'ru', 0, 'ПВХ-пергола арочная — элегантный дизайн с проверенной функциональностью', '["ПВХ-пергола арочная — это элегантная версия ПВХ-перголы, основанная на той же гибкой водостойкой крыше-полотне, но с уникальной дугообразной формой вместо стандартной прямой. Арочная форма придаёт пространству престижный и архитектурный облик, и особенно подходит тем, кто ищет решение для затенения, сочетающее выразительную эстетику с полной функциональностью.","Ключевые технические характеристики:"]'::jsonb, '["Гибкая крыша-полотно арочной формы, устойчивая к воде и погодным условиям Израиля.","Полная защита от солнца и дождя, с быстрым закрытием при необходимости.","ПВХ-ткань устойчива к УФ-излучению и не желтеет со временем.","Простое электрическое управление, как и в прямой модели перголы.","Уникальный архитектурный облик, подходящий для пространств, где дизайн является ключевым фактором."]'::jsonb, '["Как и обычная ПВХ-пергола, арочная версия устойчива к климатическим условиям Израиля — жаре, сезонным ветрам и дождю — и обеспечивает быструю и полную защиту одним нажатием кнопки. Главное отличие — в дизайнерской линии: дугообразная форма добавляет мягкости и визуальной изысканности по сравнению с прямой минималистичной линией стандартной модели. Пергола производится по индивидуальным размерам на нашем заводе в Израиле и профессионально устанавливается по всей стране — в центре, на севере и на юге."]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('model', 'pvc-pergula', 'he', 0, 'פרגולת PVC - פתרון יעיל וגמיש לצל ולהגנה מגשם', '["פרגולת PVC היא פתרון יעיל לצל ולהגנה מהגשם, המבוסס על גג יריעה גמיש במקום שלבי אלומיניום מסתובבים. בד ה-PVC העמיד נשלט חשמלית ומאפשר סגירה מהירה ומלאה בעת גשם, ללא צורך בכיוונון זוויות או תפעול מורכב.","מאפיינים טכניים מרכזיים:"]'::jsonb, '["גג יריעה גמיש ועמיד למים, במקום שלבים מסתובבים","שליטה חשמלית פשוטה, המאפשרת סגירה מהירה בעת שינוי מזג אוויר","בד עמיד בפני קרינת UV ואינו מצהיב עם הזמן","פתרון מהיר ואמין, ללא צורך בכיוונון עדין","מיוצר בגרסה ישרה או קשתית, לפי הצורך העיצובי"]'::jsonb, '["הדגם אידיאלי למסעדות, מרפסות ובתי קפה שרוצים פתרון מהיר ואמין להגנה מגשם ושמש, ללא הצורך במכניקה מורכבת של שלבים מסתובבים כמו בדגמי הביוקלימטיק. בשונה מהם, פרגולת ה-PVC מתמקדת בפשטות תפעולית ובמענה מיידי לשינויים במזג האוויר - לחיצת כפתור אחת סוגרת את המבנה במלואו. הפרגולה מיוצרת לפי מידה במפעל שלנו בישראל ומותקנת מקצועית בכל רחבי הארץ - במרכז, בצפון ובדרום."]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('model', 'pvc-pergula', 'ru', 0, 'ПВХ-пергола — эффективное и гибкое решение для тени и защиты от дождя', '["ПВХ-пергола — это эффективное решение для создания тени и защиты от дождя, основанное на гибкой крыше-полотне вместо поворотных алюминиевых ламелей. Устойчивая ПВХ-ткань управляется электрически и обеспечивает быстрое и полное закрытие во время дождя, без необходимости настройки углов или сложного управления.","Ключевые технические характеристики:"]'::jsonb, '["Гибкая водостойкая крыша-полотно вместо поворотных ламелей.","Простое электрическое управление, обеспечивающее быстрое закрытие при изменении погоды.","Ткань устойчива к УФ-излучению и не желтеет со временем.","Быстрое и надёжное решение, не требующее тонкой настройки.","Производится в прямой или арочной версии, в зависимости от дизайнерских предпочтений."]'::jsonb, '["Модель идеальна для ресторанов, балконов и кафе, которым нужно быстрое и надёжное решение для защиты от дождя и солнца без сложной механики поворотных ламелей, как в моделях биоклиматика. В отличие от них, ПВХ-пергола ориентирована на простоту эксплуатации и мгновенную реакцию на изменение погоды — одним нажатием кнопки конструкция полностью закрывается. Пергола производится по индивидуальным размерам на нашем заводе в Израиле и профессионально устанавливается по всей стране — в центре, на севере и на юге."]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('model', 'rafafa', 'he', 0, 'ביוקלימטיק רפפה - עיצוב דינמי עם פונקציונליות מלאה', '["ביוקלימטיק רפפה הוא פתרון עיצובי ייחודי בקטגוריית הפרגולות החשמליות, המשלב פונקציונליות עם אסתטיקה בולטת. הלוחות המתנדנדים יוצרים תנועה עדינה ברוח, ומעניקים לחלל מראה דינמי ומיוחד שאינו קיים בדגמי הביוקלימטיק האחרים."]'::jsonb, '["לוחות מתנדנדים היוצרים תנועה עדינה וטבעית ברוח","מראה דינמי ומיוחד, המבדל את הדגם משאר הפרגולות החשמליות","הגנה מהשמש ומתנאי מזג האוויר, לצד האפקט הוויזואלי","מתאים לחללים בהם חשוב שילוב בין עיצוב ייחודי לפונקציונליות"]'::jsonb, '["מאפיינים מרכזיים:"]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('model', 'rafafa', 'ru', 0, 'Биоклиматик Рафафа — динамичный дизайн с полной функциональностью', '["Биоклиматик Рафафа — это уникальное дизайнерское решение в категории электрических пергол, сочетающее функциональность с выразительной эстетикой. Раскачивающиеся панели создают лёгкое движение на ветру, придавая пространству динамичный и особенный облик, которого нет у других моделей биоклиматика."]'::jsonb, '["Раскачивающиеся панели, создающие лёгкое и естественное движение на ветру.","Динамичный и особенный внешний вид, отличающий модель от остальных электрических пергол.","Защита от солнца и погодных условий, наряду с визуальным эффектом.","Подходит для пространств, где важно сочетание уникального дизайна с функциональностью."]'::jsonb, '["Ключевые особенности:"]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('model', 'hi-tec-yashir', 'he', 0, 'פרגולת היי-טק פסים חלקים - קו עיצובי נקי ומינימליסטי', '["פרגולת היי-טק פסים חלקים היא פרגולה סטטית מקטגוריית הפרגולות הקבועות, המבוססת על פרופילי אלומיניום ישרים בעיצוב מינימליסטי נקי. הפסים הישרים והחלקים יוצרים מראה מודרני ואלגנטי, המשתלב עם כל סגנון אדריכלי עכשווי.","מאפיינים מרכזיים:"]'::jsonb, '["פרופילי אלומיניום ישרים וחלקים, ללא תוספות עיצוביות","מראה מודרני ואלגנטי, מתאים לכל סגנון אדריכלי עכשווי","קו עיצובי נקי ומינימליסטי, ללא רעש ויזואלי","מתאימה לבתים פרטיים, גגות ומרחבים חיצוניים"]'::jsonb, '["הדגם מתאים במיוחד לבתים פרטיים, גגות ומרחבים חיצוניים המחפשים קו נקי ומושלם, ללא פסי צד דקורטיביים או אלמנטים עיצוביים נוספים - הפשטות עצמה היא הצהרת העיצוב. כמו שאר הפרגולות הקבועות, המבנה עשוי משלד אלומיניום איכותי, מיוצר לפי מידה בכל גוון ממניפת RAL, ומותקן מקצועית בכל רחבי הארץ - במרכז, בצפון ובדרום."]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('model', 'hi-tec-yashir', 'ru', 0, 'Пергола хай-тек с гладкими планками — чистая минималистичная линия', '["Пергола хай-тек с гладкими планками — это стационарная конструкция из категории неподвижных пергол, основанная на прямых алюминиевых профилях в минималистичном чистом дизайне. Прямые и гладкие планки создают современный и элегантный облик, гармонично сочетающийся с любым современным архитектурным стилем.","Ключевые особенности:"]'::jsonb, '["Прямые и гладкие алюминиевые профили, без дополнительных декоративных элементов.","Современный и элегантный внешний вид, подходящий для любого современного архитектурного стиля.","Чистая минималистичная дизайнерская линия, без визуального «шума».","Подходит для частных домов, крыш и открытых пространств."]'::jsonb, '["Модель особенно подходит для частных домов, крыш и открытых пространств, где ищут чёткую и совершенную линию без боковых декоративных планок или дополнительных элементов дизайна — сама простота становится главным дизайнерским высказыванием. Как и остальные стационарные перголы, конструкция изготовлена из качественного алюминиевого каркаса, производится по индивидуальным размерам в любом цвете палитры RAL и профессионально устанавливается по всей стране — в центре, на севере и на юге."]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('model', 'pergola-clasit', 'he', 0, 'פרגולה קלאסית — עיצוב אדריכלי קלאסי בביצוע מודרני', '["פרגולה קלאסית היא פרגולה סטטית מקטגוריית הפרגולות הקבועות, המשלבת קלאסיקה של עיצוב אדריכלי עם ביצוע מודרני. המבנה יוצר צל קבוע, מגן מקרינת UV ומעניק למרחב מראה אסתטי מושלם.","מאפיינים מרכזיים:"]'::jsonb, '["מסגרת אלומיניום איכותית — אינה דורשת צביעה, לא נרקבת ולא מתעוותת תחת האקלים הישראלי.","צל קבוע והגנה יעילה מקרינת UV.","מראה אסתטי קלאסי המשתלב במגוון סגנונות אדריכליים.","זמינה עם לוחות/למלות קבועים בזוויות שונות, לפי בחירה בהתאמה אישית.","ניתן לשלב תוספות: תריסי ZIP, זכוכית, תאורת LED, חיממי אינפרא‑אדום","ייצור לפי מידה ובכל צבע RAL, כולל גוונים בהירים המשקפים חום."]'::jsonb, '["ייצור והתקנה: מיוצרת בישראל, מותאמת למידות אישיות, מותקנת במקצועיות בכל הארץ (מרכז, צפון, דרום)."]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('model', 'pergola-clasit', 'ru', 0, 'Классическая пергола — классика архитектурного дизайна в современном исполнении', '["Классическая пергола — стационарная конструкция из категории неподвижных пергол, сочетающая классику архитектурного дизайна с современным исполнением. Конструкция создаёт постоянную тень, защищает от УФ‑излучения и придаёт пространству безупречный эстетический вид.","Ключевые особенности:"]'::jsonb, '["Качественный алюминиевый каркас — не требует покраски, не гниёт и не деформируется в условиях израильского климата.","Постоянная тень и эффективная защита от УФ‑излучения.","Классический эстетичный облик, гармонично сочетающийся с разными архитектурными стилями.","Доступна с фиксированными панелями/ламелями под разными углами — по индивидуальному выбору при заказе.","Возможность добавления опций: ZIP‑роллеты, стеклянное остекление, LED‑подсветка, инфракрасные обогреватели.","Производство по индивидуальным размерам, в любом цвете RAL, включая светлые теплоотражающие оттенки."]'::jsonb, '["Производство и установка: производится в Израиле, изготавливается по индивидуальным размерам, профессионально устанавливается по всей стране (центр, север, юг)."]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('model', 'panel-mevudad', 'he', 0, 'פרגולה מפנל מבודד — צל ובידוד תרמי אמיתי בפתרון קבוע אחד', '["פרגולה מפנל מבודד היא פרגולה סטטית מקטגוריית הפרגולות הקבועות, המספקת לא רק צל אלא גם בידוד תרמי ואקוסטי אמיתי. הגג מורכב מפנל מבודד בעל שתי שכבות אלומיניום עם מילוי פוליאוריתן, המבטיח בידוד תרמי מצוין וגם הפחתת רעש.","מאפיינים מרכזיים:"]'::jsonb, '["פנל דו‑שכבתי מאלומיניום עם מילוי פוליאוריתן — בידוד תרמי ואקוסטי מיטבי.","אטימות מוחלטת למים — ניתן להשתמש בשטח מתחת לפרגולה גם בזמן גשם.","משמש כגג קבוע לסוכות, פרגולות ומרפסות מקורות.","מסגרת אלומיניום איכותית, ללא צביעה חוזרת, עמידה באקלים הישראלי.","ניתן לשלב תוספות: תריסי ZIP, זכוכית, תאורת LED, חיממי אינפרא‑אדום","ייצור לפי מידה ובכל צבע RAL."]'::jsonb, '["ייצור והתקנה: מיוצרת בישראל, מותאמת למידות אישיות, מותקנת במקצועיות בכל הארץ (מרכז, צפון, דרום)."]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('model', 'panel-mevudad', 'ru', 0, 'Пергола с теплоизоляционной панелью — тень и настоящая теплоизоляция в одном постоянном решении', '["Пергола с теплоизоляционной панелью — стационарная конструкция из категории неподвижных пергол, обеспечивающая не только тень, но и настоящую тепло‑ и звукоизоляцию. Кровля выполнена из изолированной сэндвич‑панели, состоящей из двух слоёв алюминия с наполнением из полиуретана, что гарантирует превосходную теплоизоляцию и снижение уровня шума.","Ключевые особенности:"]'::jsonb, '["Двухслойная алюминиевая панель с наполнением из полиуретана — оптимальная тепло‑ и звукоизоляция.","Полная водонепроницаемость — пространство под перголой можно использовать даже во время дождя.","Служит постоянной крышей для беседок (сукка), пергол и крытых балконов.","Качественный алюминиевый каркас, не требующий повторной окраски, устойчивый к израильскому климату.","Возможность добавления опций: ZIP‑роллеты, стеклянное остекление, LED‑подсветка, инфракрасные обогреватели.","Производство по индивидуальным размерам и в любом цвете RAL."]'::jsonb, '["Производство и установка: производится в Израиле, изготавливается по индивидуальным размерам, профессионально устанавливается по всей стране (центр, север, юг)."]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('model', 'hi-tech-meutsavim', 'he', 0, 'פרגולת היי-טק פסים מעוצבים — עיצוב אדריכלי בולט ומיוחד', '["פרגולת היי-טק פסים מעוצבים היא פרגולה סטטית מקטגוריית הפרגולות הקבועות, בעלת פרופילי אלומיניום מעוצבים בצורות ייחודיות. הפסים המעוצבים מוסיפים אלמנט עיצובי בולט ומעניקים למבנה מראה מרשים ומיוחד, המבדל אותו מהדגמים הקלאסיים והמינימליסטיים.","מאפיינים מרכזיים:"]'::jsonb, '["פרופילי אלומיניום בצורות מעוצבות וייחודיות, לא סטנדרטיות.","מראה אדריכלי בולט ומרשים, מתאים למי שמחפש בידול עיצובי.","מסגרת אלומיניום איכותית, עמידה לאורך זמן, ללא צביעה חוזרת.","מתאימה לחזיתות בתים, גגות ומרפסות הדורשים מראה מיוחד.","ניתן לשלב תוספות: תריסי ZIP, זכוכית, תאורת LED, חיממי אינפרא‑אדום","ייצור לפי מידה ובכל צבע RAL."]'::jsonb, '["ייצור והתקנה: מיוצרת בישראל, מותאמת למידות אישיות, מותקנת במקצועיות בכל הארץ (מרכז, צפון, דרום)."]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('model', 'hi-tech-meutsavim', 'ru', 0, 'Пергола хай‑тек с фигурными планками — яркий и особый архитектурный дизайн', '["Пергола хай‑тек с фигурными планками — стационарная конструкция из категории неподвижных пергол, с алюминиевыми профилями, выполненными в уникальных фигурных формах. Фигурные планки добавляют яркий дизайнерский элемент и придают конструкции впечатляющий, особенный вид, отличающий её от классических и минималистичных моделей.","Ключевые особенности:"]'::jsonb, '["Алюминиевые профили нестандартной, фигурной формы.","Яркий, впечатляющий архитектурный облик для тех, кто ищет дизайнерскую индивидуальность.","Качественный, долговечный алюминиевый каркас, не требующий повторной покраски.","Подходит для фасадов домов, крыш и террас, где важен особый внешний вид.","Возможность добавления опций: ZIP‑роллеты, стеклянное остекление, LED‑подсветка, инфракрасные обогреватели.","Производство по индивидуальным размерам и в любом цвете RAL."]'::jsonb, '["Производство и установка: производится в Израиле, изготавливается по индивидуальным размерам, профессионально устанавливается по всей стране (центр, север, юг)."]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('model', 'masahey-zip', 'he', 0, 'מסכי ZIP — וילונות אנכיים אטומים ושקופים', '["מסכי ZIP הם וילונות אנכיים חדשניים מ‑PVC שקוף, הנצמדים היטב לפרופיל האלומיניום משני הצדדים הודות למדריכים צדדיים. בניגוד לוילונות רגילים, מסכי ZIP לא מתנפנפים ברוח ומבטיחים סגירה אטומה לחלוטין.","מאפיינים מרכזיים:","יישומים מומלצים: מסעדות, מרפסות, מרפסות גג, סגירת שטח בין עמודי פרגולה או בין חזיתות בניין."]'::jsonb, '["בד PVC שקוף — שומר על נראות ותצפית פתוחה גם כשהמסך סגור.","הידוק לאורך שני הצדדים באמצעות מדריכים צדדיים — ללא התנפנפות ברוח.","סגירה אטומה מלאה — הגנה מרוח ומבטים מבחוץ.","התקנה אנכית בין עמודי פרגולה או בין חזיתות הבניין.","שליטה חשמלית (שלט, מתג קיר, אפליקציה), אפשרות עצירה בכל גובה.","ייצור לפי מידות אישיות."]'::jsonb, '["ייצור והתקנה: מיוצר לפי מידה, התקנה מקצועית בכל הארץ."]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('model', 'masahey-zip', 'ru', 0, 'ZIP‑экраны — вертикальные герметичные и прозрачные полотна', '["ZIP‑экраны — это инновационные вертикальные завесы из прозрачного PVC, плотно прилегающие к алюминиевому профилю с обеих сторон благодаря боковым направляющим. В отличие от обычных штор, ZIP‑экраны не колышутся на ветру и обеспечивают полностью герметичное закрытие."]'::jsonb, '["Прозрачное PVC‑полотно — сохраняет видимость и открытый обзор даже в закрытом положении.","Фиксация с обеих сторон в боковых направляющих — без раздувания на ветру.","Полностью герметичное закрытие — защита от ветра и посторонних взглядов снаружи.","Вертикальная установка между колоннами перголы или на фасадах здания.","Электрическое управление (пульт, настенный выключатель, приложение), возможность остановки на любой высоте.","Производство по индивидуальным размерам."]'::jsonb, '["Ключевые особенности:"]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('model', 'gag-zhuhit-kavua', 'he', 0, 'גג זכוכית קבוע — כיסוי אסתטי ועמיד לחצרות ומרפסות', '["גג זכוכית קבוע הוא פתרון אסתטי ועמיד לכיסוי מרחבים פתוחים, מקטגוריית גגות הזכוכית שלנו. הזכוכית המחוסמת מספקת הגנה מלאה מהגשם תוך מעבר אור טבעי מקסימלי, ומאפשרת ליהנות משטח מקורה ללא אובדן תחושת המרחב הפתוח.","מאפיינים מרכזיים:","מתאים ל: חצרות, מרפסות וגגות המחפשים כיסוי קבוע ואסתטי ללא אובדן אור טבעי; בתים פרטיים, וילות, מסעדות, בתי קפה וחללים מסחריים."]'::jsonb, '["זכוכית מחוסמת — הגנה מלאה מגשם ומעבר אור טבעי מקסימלי.","מסגרת אלומיניום חזקה ועמידה, מותאמת לתנאי מזג האוויר הישראלי (חום, רוחות עונתיות, גשם).","פתרון קבוע ואמין ללא צורך בתחזוקה שוטפת או הפעלה חשמלית.","ניתן לשלב עם תריסי ZIP או מערכות סגירה להגנה נוספת מהשמש.","שלד בצביעת תנור בכל גוון RAL."]'::jsonb, '["ייצור והתקנה: מיוצר בישראל, לפי מידות אישיות, מותקן במקצועיות בכל הארץ (מרכז, צפון, דרום)."]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('model', 'gag-zhuhit-kavua', 'ru', 0, 'Стационарная стеклянная крыша — эстетичное и прочное укрытие для дворов и террас', '["Стационарная стеклянная крыша — эстетичное и долговечное решение для покрытия открытых пространств из категории наших стеклянных крыш. Закалённое стекло обеспечивает полную защиту от дождя при максимальном пропускании естественного света, позволяя наслаждаться крытым пространством без потери ощущения открытости.","Ключевые особенности:","Подходит для: дворов, балконов и крыш, которые нужно накрыть без потери естественного освещения; частных домов, вилл, ресторанов, кафе и коммерческих пространств."]'::jsonb, '["Закалённое стекло — полная защита от дождя и максимальное пропускание естественного света.","Прочный алюминиевый каркас, устойчивый к условиям израильского климата (жара, сезонные ветра, дожди).","Надёжное стационарное решение, не требующее регулярного обслуживания или электрического привода.","Возможность сочетания с ZIP‑роллетами или другими системами закрытия для дополнительной защиты от солнца.","Каркас с печной окраской в любом цвете RAL."]'::jsonb, '["Производство и установка: производится в Израиле, по индивидуальным размерам, профессионально устанавливается по всей стране (центр, север, юг)."]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('model', 'neesafot', 'he', 0, 'זכוכיות נאספות — מיזוג מושלם בין פנים לחוץ', '["זכוכיות נאספות היא מערכת פאנלים זכוכית שמתקפלים כמו אקורדיון ופותחים את המרחב לחלוטין. ללא עמודי אלומיניום גלויים — רק זכוכית, ליצירת חופש מבט מקסימלי ותחושת מרחב פתוח.","מאפיינים מרכזיים:","מתאים ל: מרפסות, גגות ומרפסות קיץ, גינות חורף, מסעדות ובתי קפה, חללים מסחריים."]'::jsonb, '["מערכת פאנלים המתקפלת כמו אקורדיון, פתיחה מלאה של הפתח.","ללא עמודי אלומיניום נראים לעין — הזכוכית היא היחידה שנראית.","זכוכית מחוסמת לבטיחות מקסימלית.","הגנה מפני רוח, גשם ורעש כשהמערכת סגורה.","אידיאלי לאיחוד חלל פנימי וחיצוני."]'::jsonb, '["ייצור והתקנה: ייצור לפי מידה, התקנה מקצועית בכל הארץ."]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('model', 'neesafot', 'ru', 0, 'Раздвижное остекление — идеальное объединение внутреннего и внешнего пространства', '["Раздвижное остекление — система стеклянных панелей, складывающихся по принципу гармошки и полностью открывающих пространство. Без видимых алюминиевых стоек — только стекло, для максимальной свободы обзора и ощущения открытого пространства.","Ключевые особенности:","Подходит для: балконов, крыш и летних террас, зимних садов, ресторанов и кафе, коммерческих пространств."]'::jsonb, '["Система панелей, складывающихся по типу гармошки, полное открытие проёма.","Отсутствие видимых алюминиевых стоек — виден только стеклянный массив.","Закалённое стекло для максимальной безопасности.","Защита от ветра, дождя и шума в закрытом положении.","Идеально для объединения внутреннего и внешнего пространства."]'::jsonb, '["Производство и установка: производство по индивидуальным размерам, профессиональная установка по всей стране."]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('model', 'tzalon-kalua', 'he', 0, 'נאספות עם צלון כלוא — שליטה מלאה על אור ופרטיות', '["נאספות עם צלון כלוא הוא פתרון מתקדם המשלב זכוכיות נאספות (מערכת פאנלים המתקפלת ופותחת את המרחב לחלוטין) עם צלון ונציאני משולב בתוך הזכוכית. הצלון מאפשר שליטה מלאה על כמות האור והפרטיות ללא צורך בוילונות נפרדים.","מאפיינים מרכזיים:","מתאים ל: חדרי שינה, חדרי ישיבות ומרפסות בהן חשובה הפרטיות, בנוסף למרפסות, גינות חורף, מסעדות וחללים מסחריים."]'::jsonb, '["מערכת זכוכיות נאספות המשלבת צלון ונציאני מובנה בתוך זכוכית בידודית (4 מ\"מ + חלל אוויר 22 מ\"מ + 4 מ\"מ).","סביבה אטומה לחלוטין — ללא אבק וללא צורך בתחזוקה של הצלון.","שליטה מלאה על כמות האור והפרטיות, ללא צורך בוילונות או תריסים נוספים.","זכוכית מחוסמת לבטיחות מקסימלית.","הגנה מפני רוח, גשם ורעש כשהמערכת סגורה."]'::jsonb, '["ייצור והתקנה: ייצור לפי מידה, התקנה מקצועית בכל הארץ."]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('model', 'tzalon-kalua', 'ru', 0, 'Раздвижное остекление со встроенными жалюзи — полный контроль света и приватности', '["Раздвижное остекление со встроенными жалюзи — продвинутое решение, сочетающее систему раздвижных стеклянных панелей (полностью открывающих пространство) с венецианскими жалюзи, встроенными внутрь стекла. Жалюзи обеспечивают полный контроль количества света и уровня приватности без необходимости в отдельных занавесках.","Ключевые особенности:","Подходит для: спален, переговорных комнат и балконов, где важна приватность, а также балконов, зимних садов, ресторанов и коммерческих пространств."]'::jsonb, '["Система раздвижного остекления со встроенными венецианскими жалюзи внутри изолирующего стеклопакета (4 мм + воздушный зазор 22 мм + 4 мм).","Полностью герметичная среда — без пыли и необходимости обслуживания жалюзи.","Полный контроль количества света и приватности без дополнительных занавесок или штор.","Закалённое стекло для максимальной безопасности.","Защита от ветра, дождя и шума в закрытом положении."]'::jsonb, '["Производство и установка: производство по индивидуальным размерам, профессиональная установка по всей стране."]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('model', 'skylight', 'he', 0, 'סקיילייט חשמלי — שליטה קלה באור ובאוורור', '["סקיילייט חשמלי הוא גג זכוכית ממונע המאפשר שליטה קלה על כמות האור והאוורור, מקטגוריית גגות הזכוכית שלנו. פתיחה וסגירה חשמלית בלחיצת כפתור, עם חיישני גשם מובנים הסוגרים את הגג באופן אוטומטי בעת ירידת גשם.","מאפיינים מרכזיים:","מתאים ל: פתרון פרימיום לגגות וטרסות, בתים פרטיים, וילות, מסעדות, בתי קפה וחללים מסחריים."]'::jsonb, '["פתיחה וסגירה חשמלית בלחיצת כפתור — שליטה מלאה באוורור ובטמפרטורה בזמן אמת.","חיישני גשם מובנים לסגירה אוטומטית בעת מזג אוויר גרוע.","זכוכית מחוסמת חזקה ובטיחותית, המספקת גם בידוד תרמי ואקוסטי.","מסגרת אלומיניום עמידה עם צביעה בתנור בכל גוון RAL.","ניתן לשלב עם תריסי ZIP או מערכות סגירה נוספות."]'::jsonb, '["ייצור והתקנה: מיוצר בישראל, לפי מידות אישיות, מותקן במקצועיות בכל הארץ (מרכז, צפון, דרום)."]'::jsonb);
INSERT INTO content_blocks (owner_type, owner_slug, lang, position, heading, paragraphs, items, outro) VALUES ('model', 'skylight', 'ru', 0, 'Электрический скайлайт — простой контроль света и вентиляции', '["Электрический скайлайт — моторизированная стеклянная крыша, обеспечивающая простое управление количеством света и вентиляцией, из категории наших стеклянных крыш. Электрическое открытие и закрытие нажатием кнопки, со встроенными датчиками дождя, автоматически закрывающими крышу при осадках.","Ключевые особенности:","Подходит для: премиального решения для крыш и террас, частных домов, вилл, ресторанов, кафе и коммерческих пространств."]'::jsonb, '["Электрическое открытие и закрытие нажатием кнопки — полный контроль вентиляции и температуры в реальном времени.","Встроенные датчики дождя для автоматического закрытия в плохую погоду.","Прочное и безопасное закалённое стекло, обеспечивающее также тепло‑ и звукоизоляцию.","Прочный алюминиевый каркас с печной окраской в любом цвете RAL.","Возможность сочетания с ZIP‑роллетами или другими системами закрытия."]'::jsonb, '["Производство и установка: производится в Израиле, по индивидуальным размерам, профессионально устанавливается по всей стране (центр, север, юг)"]'::jsonb);
INSERT INTO faq_items (lang, position, question, answer) VALUES ('he', 0, 'האם אני צריך היתר בנייה כדי להתקין פרגולה?', 'אנו מסייעים ללקוחותינו בקבלת היתר בנייה ממהנדס מוסמך כחלק מתהליך ההזמנה ומסייעים לכם בהגשת המסמכים הדרושים לרשויות המקומיות.');
INSERT INTO faq_items (lang, position, question, answer) VALUES ('he', 1, 'כמה עומדת פרגולת אלומיניום בפני רוח וגשם?', 'כל המבנים שלנו מתוכננים ומיוצרים לעמידה בתנאי מזג האוויר בישראל, כולל רוחות עונתיות וגשם חזק. פרגולות חשמליות ביוקלימטיות מגיעות עם מערכת ניקוז נסתרת ואטימות מלאה כשהשלבים סגורים, ולעיתים ניתן להוסיף חיישני רוח וגשם לסגירה אוטומטית במקרה הצורך.');
INSERT INTO faq_items (lang, position, question, answer) VALUES ('he', 2, 'מה ההבדל בין פרגולה ביוקלימטית לפרגולת PVC?', 'פרגולה ביוקלימטית מבוססת על שלבי אלומיניום מתכווננים בזווית של 0° עד 90°, המאפשרים שליטה מדויקת באור, בצל ובאוורור. פרגולת PVC, לעומת זאת, מבוססת על גג יריעה גמיש ועמיד למים ואינה מציעה שליטה בזווית - היא נפתחת או נסגרת כמקבץ אחד. הבחירה בין השתיים תלויה בעיקר ברמת השליטה הנדרשת באור ובאוורור לאורך היום.');
INSERT INTO faq_items (lang, position, question, answer) VALUES ('he', 3, 'איזו אחריות מקבלים על המבנה?', 'Vitlion Group מספקת אחריות כתובה של 10 שנים על כל מבנה שאנחנו מייצרים ומתקינים, הכוללת כיסוי על תקינות המבנה והמנגנונים החשמליים בשימוש רגיל.');
INSERT INTO faq_items (lang, position, question, answer) VALUES ('he', 4, 'האם פרגולת אלומיניום דורשת תחזוקה שוטפת?', 'לא. בשונה מפרגולות עץ, אלומיניום אינו דורש צביעה או טיפול תקופתי מפני חלודה או ריקבון. שטיפה קלה במים מדי פעם מספיקה לשמירה על המראה והתפקוד התקין של המבנה לאורך שנים.');
INSERT INTO faq_items (lang, position, question, answer) VALUES ('ru', 0, 'Требуется ли разрешение на строительство для установки перголы?', 'Мы помогаем нашим клиентам получить разрешение на строительство от сертифицированного инженера в рамках процесса заказа и даем консультацию по прохождению получения разрешения у местных органов власти.');
INSERT INTO faq_items (lang, position, question, answer) VALUES ('ru', 1, 'Насколько хорошо алюминиевая пергола выдерживает ветер и дождь?', 'Все наши конструкции спроектированы и произведены с учётом климатических условий Израиля, включая сезонные ветры и сильные дожди. Электрические биоклиматические перголы оснащены скрытой системой водоотвода и обеспечивают полную герметичность при закрытых ламелях, а при необходимости можно установить датчики ветра и дождя для автоматического закрытия конструкции.');
INSERT INTO faq_items (lang, position, question, answer) VALUES ('ru', 2, 'Чем биоклиматическая пергола отличается от перголы из ПВХ?', 'Биоклиматическая пергола основана на регулируемых алюминиевых ламелях с углом наклона от 0° до 90°, что позволяет точно контролировать освещённость, тень и вентиляцию. Пергола из ПВХ, в свою очередь, основана на гибком и водостойком полотняном покрытии и не предполагает регулировки угла — она открывается или закрывается как единое целое. Выбор между этими двумя типами зависит главным образом от того, насколько важен для вас точный контроль над светом и вентиляцией в течение дня.');
INSERT INTO faq_items (lang, position, question, answer) VALUES ('ru', 3, 'Какая гарантия предоставляется на конструкцию?', 'Vitlion Group предоставляет письменную гарантию на 10 лет на каждую произведённую и установленную нами конструкцию, включающую покрытие исправности самого сооружения и электрических механизмов при обычном использовании.');
INSERT INTO faq_items (lang, position, question, answer) VALUES ('ru', 4, 'Требует ли алюминиевая пергола постоянного обслуживания?', 'Нет. В отличие от деревянных пергол, алюминий не требует окраски или периодической обработки от коррозии или гниения. Лёгкого мытья водой время от времени достаточно для поддержания внешнего вида и исправной работы конструкции на протяжении многих лет.');
